  for e in select * from (values
    (3, 'terme.umformen', 777, 15, $auf$[{"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du fasst 9x + 3y − 2x + 5y zusammen. Das Ergebnis hat die Form ① · x + ② · y. Für x = 2 und y = 1 hat der Term den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 8, 22]}, "h": "Fasse nur gleichartige Glieder zusammen: die mit x und die mit y. Setze die Zahlen für x und y erst am Ende ein.", "w": "x-Glieder: 9x − 2x = 7x. y-Glieder: 3y + 5y = 8y. Der Term ist 7x + 8y. Für x = 2 und y = 1: 7 · 2 + 8 · 1 = 22. Probe mit dem Ausgangsterm: 18 + 3 − 4 + 5 = 22.", "form": "lueckenweg", "zaehlt": "nein", "r": 15778}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim kauft 3 Erwachsenen- und 2 Kinderkarten für einen Freizeitpark, Alex kauft 5 Erwachsenen- und 4 Kinderkarten. Eine Erwachsenenkarte kostet a €, eine Kinderkarte b €. Zusammen zahlen sie 3a + 2b + 5a + 4b. Wie viel Euro sind das für a = 12 und b = 7?"}, "o": {"wert": 138, "einheit": "€"}, "h": "Fasse erst zusammen: Wie viele Erwachsenenkarten sind es insgesamt, wie viele Kinderkarten?", "w": "Erwachsenenkarten: 3a + 5a = 8a. Kinderkarten: 2b + 4b = 6b. Zusammen 8a + 6b. Für a = 12 und b = 7: 8 · 12 + 6 · 7 = 96 + 42 = 138 €.", "form": "anwenden", "zaehlt": "ja", "r": 15779}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim soll 6x + 5y − 2x + y zusammenfassen und schreibt auf: Zeile 1: Gleichartig sind 6x und −2x sowie 5y und y. Zeile 2: 6x − 2x = 4x. Zeile 3: 5y + y = 5y, denn ein einzelnes y hat keine Zahl davor. Zeile 4: Das Ergebnis ist 4x + 5y. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Welche Zahl steht vor einem einzelnen y? Prüfe es mit y = 1: y ist dann 1 · y.", "w": "Ein einzelnes y bedeutet 1y. Also gilt 5y + y = 5y + 1y = 6y. Das richtige Ergebnis ist 4x + 6y. Der Fehler steckt in Zeile 3. Zeile 4 übernimmt ihn.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15780}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Reisebox ist ein Quader mit den Kanten 2a, 3a und a (in Zentimetern). Das Volumen ist das Produkt der drei Kanten. Wie groß ist das Volumen in Kubikzentimetern für a = 5?"}, "o": {"wert": 750, "einheit": "cm³"}, "h": "Vereinfache das Produkt zuerst: Zahlen mal Zahlen, gleiche Buchstaben zu einer Potenz.", "w": "2a · 3a · a = (2 · 3) · (a · a · a) = 6a³. Für a = 5: 6 · 5³ = 6 · 125 = 750 cm³.", "form": "anwenden", "zaehlt": "ja", "r": 15781}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Welches Produkt ergibt −12a²b?"}, "a": ["(−3a) · (−4ab)", "3a · (−4ab)", "(−3a) · 4a", "3a · 4b"], "o": {"index": 1}, "h": "Zerlege −12a²b in Faktoren: Welche Vorzeichen, Zahlen und Buchstaben müssen links zusammenkommen? Prüfe jedes Angebot durch Ausrechnen.", "w": "3a · (−4ab) = −12a²b: Plus mal Minus gibt Minus, 3 · 4 = 12 und a · a · b = a²b. Die anderen Produkte ergeben (−3a) · (−4ab) = 12a²b, (−3a) · 4a = −12a² und 3a · 4b = 12ab.", "form": "umkehren", "zaehlt": "ja", "r": 15782}, {"l": "produkte", "t": "produkte", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine natürliche Zahl a erfüllt 3a · 4a = 300. Wie groß ist a?"}, "o": {"wert": 5}, "h": "Vereinfache zuerst das Produkt auf der linken Seite. Welche natürliche Zahl mal sich selbst ergibt das Ergebnis?", "w": "3a · 4a = 12a². Aus 12a² = 300 folgt a² = 25. Nur die natürliche Zahl 5 hat das Quadrat 25. Probe: 3 · 5 · 4 · 5 = 15 · 20 = 300.", "form": "umkehren", "zaehlt": "ja", "r": 15783}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du löst die Klammer in 11x − (4x − 6) + 3 auf und fasst zusammen. Das Ergebnis hat die Form ① · x + ②. Für x = 2 hat der Term den Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 9, 23]}, "h": "Ein Minus vor der Klammer ändert die Vorzeichen aller Glieder in der Klammer. Achte besonders auf das zweite Glied.", "w": "−(4x − 6) = −4x + 6. Dann: 11x − 4x + 6 + 3 = 7x + 9. Für x = 2: 7 · 2 + 9 = 23. Probe mit dem Ausgangsterm: 22 − (8 − 6) + 3 = 22 − 2 + 3 = 23.", "form": "lueckenweg", "zaehlt": "nein", "r": 15784}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim hat 400 € Reisegeld. Für eine Zugfahrt zahlt sie (3x + 15) €, dabei ist x die Zahl der Fahrtstunden, 15 € sind eine feste Gebühr. Der Rest ist 400 − (3x + 15). Wie viel Euro bleiben bei 20 Stunden Fahrt übrig?"}, "o": {"wert": 325, "einheit": "€"}, "h": "Löse zuerst die Klammer auf. Das Minus davor wirkt auf beide Glieder in der Klammer.", "w": "400 − (3x + 15) = 400 − 3x − 15 = 385 − 3x. Für x = 20: 385 − 60 = 325 €. Probe: Die Fahrt kostet 3 · 20 + 15 = 75 €, und 400 − 75 = 325 €.", "form": "anwenden", "zaehlt": "ja", "r": 15785}, {"l": "minusklammer", "t": "minusklammer", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex löst die Klammer in 9a − (2a + 7b − 3) auf und schreibt auf: Zeile 1: Das Minus vor der Klammer ändert alle Vorzeichen in der Klammer. Zeile 2: 9a − (2a + 7b − 3) = 9a − 2a − 7b − 3. Zeile 3: Zusammengefasst ist das 7a − 7b − 3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie lautet die Klammer nach dem Auflösen, wenn bei jedem Glied das Vorzeichen wechselt? Was passiert mit −3?", "w": "Aus −(−3) wird +3. Richtig ist 9a − 2a − 7b + 3 = 7a − 7b + 3. Der Fehler steckt in Zeile 2: Das letzte Vorzeichen wurde nicht gewechselt. Zeile 3 rechnet mit diesem Fehler richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15786}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Gruppe von 6 Personen bucht ein Hostel. Pro Person kostet das Paket (45 + 12n) €, dabei ist n die Zahl der Zusatznächte. Der Gesamtpreis ist 6 · (45 + 12n). Wie viel Euro zahlt die Gruppe bei 3 Zusatznächten?"}, "o": {"wert": 486, "einheit": "€"}, "h": "Der Faktor 6 gilt für jedes Glied in der Klammer. Du kannst auch erst die Klammer ausrechnen und dann mit 6 malnehmen.", "w": "Ausmultiplizieren: 6 · (45 + 12n) = 270 + 72n. Für n = 3: 270 + 216 = 486 €. Probe: Pro Person 45 + 36 = 81 €, für 6 Personen 486 €.", "form": "anwenden", "zaehlt": "ja", "r": 15787}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Berechne 8 · 197 auf zwei Wegen. Weg A: Schriftlich malnehmen. Weg B: 197 als 200 − 3 schreiben und 8 · (200 − 3) ausmultiplizieren. Welches Ergebnis ist richtig?"}, "o": {"wert": 1576}, "h": "Bei Weg B: Der Faktor 8 trifft beide Glieder in der Klammer, auch das zweite mit seinem Minus.", "w": "Weg B: 8 · (200 − 3) = 8 · 200 − 8 · 3 = 1 600 − 24 = 1 576. Weg A schriftlich: 8 · 7 = 56, schreibe 6 und merke 5; 8 · 9 = 72 und 5 dazu sind 77, schreibe 7 und merke 7; 8 · 1 = 8 und 7 dazu sind 15. Das Ergebnis ist 1 576. Beide Wege stimmen überein.", "form": "zwei_wege", "zaehlt": "ja", "r": 15788}, {"l": "ausmultiplizieren", "t": "ausmultiplizieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Welche Zahl gehört in das Kästchen, damit 5 · (2x + □) = 10x + 35 für jede Zahl x stimmt?"}, "o": {"wert": 7}, "h": "Der Faktor 5 muss mit jedem Glied der Klammer malgenommen den passenden Summanden rechts ergeben.", "w": "Ausmultipliziert: 5 · 2x = 10x und 5 · □ = 35. Also ist □ = 35 : 5 = 7. Probe: 5 · (2x + 7) = 10x + 35.", "form": "umkehren", "zaehlt": "ja", "r": 15789}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Kim berechnet den Preis einer Taxifahrt mit 2(x + 5) − x, Alex mit x + 10. Welche Aussage über die beiden Terme ist mathematisch richtig begründet?"}, "a": ["Sie sind äquivalent, denn für x = 0 ergeben beide Terme 10.", "Sie sind nicht äquivalent: 2(x + 5) − x = 2x + 5 − x = x + 5.", "Sie sind äquivalent: 2(x + 5) − x = 2x + 10 − x = x + 10."], "o": {"index": 2}, "h": "Äquivalent heißt: für jede Zahl gleich. Forme den ersten Term um und vergleiche mit dem zweiten.", "w": "2(x + 5) − x = 2x + 10 − x = x + 10. Das ist der Term von Alex, die beiden Terme sind also für jede Zahl x gleich. Ein Beispiel allein (x = 0) würde das nicht beweisen.", "form": "anwenden", "zaehlt": "ja", "r": 15790}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Kim behauptet: „3x + 6 und 9x sind äquivalent.“ Welche Probe zeigt, dass das nicht stimmt?"}, "a": ["Für x = 1 ergeben beide Terme 9. Also sind sie nicht äquivalent.", "Für x = 1 ergeben beide Terme 9. Also sind sie äquivalent.", "3x + 6 hat zwei Glieder und 9x nur eines. Also sind sie nicht äquivalent.", "Für x = 0 ergibt der erste Term 6 und der zweite 0. Die Werte sind verschieden."], "o": {"index": 3}, "h": "Für „nicht äquivalent“ reicht eine einzige Zahl, bei der die beiden Terme verschiedene Werte haben. Probiere kleine Zahlen.", "w": "Für x = 0: 3 · 0 + 6 = 6 und 9 · 0 = 0. Die Werte sind verschieden, die Terme sind nicht äquivalent. Bei x = 1 sind beide Werte 9; das reicht nicht, um etwas zu zeigen.", "form": "umkehren", "zaehlt": "ja", "r": 15791}, {"l": "aequivalenz", "t": "aequivalenz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welchen Wert von k sind die Terme 13(x + 4) und 13x + k äquivalent?"}, "o": {"wert": 52}, "h": "Multipliziere die Klammer aus. Die Terme müssen für jede Zahl x denselben Wert haben.", "w": "13(x + 4) = 13x + 52. Damit 13x + k für jedes x denselben Wert hat, muss k = 52 sein. Probe: Für x = 1 sind beide Werte 65.", "form": "umkehren", "zaehlt": "ja", "r": 15792}]$auf$::jsonb),
    (5, 'gleichungen.linear', 604, 17, $auf$[{"l": "waage", "t": "umformen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du löst 6x − 23 = 2x + 37 mit der Waage. Subtrahiere auf beiden Seiten 2x, dann steht links ① · x − 23. Addiere auf beiden Seiten 23, dann steht rechts die Zahl ②. Zum Schluss ist x = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 60, 15]}, "h": "Was du auf der einen Seite tust, tust du auf der anderen Seite auch. Erst die x-Glieder sammeln, dann die Zahlen.", "w": "6x − 2x = 4x. Dann 4x − 23 = 37, nach Addieren von 23 ist 4x = 60. Teilen durch 4 gibt x = 15. Probe: 6 · 15 − 23 = 67 und 2 · 15 + 37 = 67.", "form": "lueckenweg", "zaehlt": "nein", "r": 15605}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Für ein Leihrad am Gardasee zahlt man 14 € Grundgebühr und dazu 3,50 € je Stunde. Alex zahlt insgesamt 49 €. Wie viele Stunden war das Rad geliehen?"}, "o": {"wert": 10, "einheit": "h"}, "h": "Beschreibe die Rechnung mit einer Gleichung: 14 + 3,5 · x = 49. Löse sie mit der Waage.", "w": "Gleichung: 14 + 3,5x = 49. Subtrahiere 14: 3,5x = 35. Teile durch 3,5: x = 10. Das Rad war 10 Stunden geliehen. Probe: 14 + 3,5 · 10 = 49.", "form": "anwenden", "zaehlt": "ja", "r": 15606}, {"l": "waage", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Sam löst 4x + 9 = 6x − 5 mit der Waage: Zeile 1: Auf der linken Seite subtrahiere ich 4x, dann bleibt 9 = 6x − 5. Zeile 2: Addiere ich 5, steht dort 14 = 6x. Zeile 3: Teile ich durch 6, ist x = 7/3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Prüfe Zeile 1: Auf welchen Seiten wurde 4x subtrahiert? Was steht dann rechts?", "w": "Die Waage bleibt nur im Gleichgewicht, wenn man auf beiden Seiten dasselbe tut. In Zeile 1 wurde 4x nur links subtrahiert. Richtig: 9 = 2x − 5, dann 14 = 2x und x = 7. Die Zeilen 2 und 3 rechnen mit dem falschen Ergebnis aus Zeile 1 richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15607}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Beim Telefonieren im Ausland hat Tarif A eine Grundgebühr von 18 € und 0,25 € je Minute. Tarif B hat keine Grundgebühr und kostet 0,40 € je Minute. Nach wie vielen Minuten Gesprächszeit kosten beide Tarife gleich viel?"}, "o": {"wert": 120, "einheit": "min"}, "h": "Stelle für beide Tarife den Preis nach x Minuten auf und setze die Preise gleich.", "w": "Tarif A: 18 + 0,25x. Tarif B: 0,40x. Gleichsetzen: 18 + 0,25x = 0,40x. Subtrahiere 0,25x: 18 = 0,15x. Teile durch 0,15: x = 120 Minuten. Probe: 18 + 30 = 48 und 0,40 · 120 = 48.", "form": "anwenden", "zaehlt": "ja", "r": 15608}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Gleichung hat dieselbe Lösung wie 8x − 30 = 3x + 25?"}, "a": ["5x = 55", "11x = 55", "5x = −5", "5x = 25"], "o": {"index": 0}, "h": "Löse die gegebene Gleichung und prüfe, bei welcher Gleichung dieselbe Zahl herauskommt.", "w": "8x − 30 = 3x + 25. Subtrahiere 3x: 5x − 30 = 25. Addiere 30: 5x = 55, also x = 11. Die Gleichung 5x = 55 hat ebenfalls die Lösung 11. Die anderen haben die Lösungen 5, −1 und 5.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15609}, {"l": "beide_seiten", "t": "umformen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Zahl haben die Terme 7x − 8 und 3x + 40 denselben Wert?"}, "o": {"wert": 12}, "h": "Setze die beiden Terme gleich und löse die Gleichung.", "w": "7x − 8 = 3x + 40. Subtrahiere 3x: 4x − 8 = 40. Addiere 8: 4x = 48. Teile durch 4: x = 12. Probe: 7 · 12 − 8 = 76 und 3 · 12 + 40 = 76.", "form": "umkehren", "zaehlt": "ja", "r": 15610}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du löst 5(x − 4) = 2x + 19. Nach dem Ausmultiplizieren steht links 5x − ①. Subtrahiere 2x, dann steht links 3x − ①. Addiere ① auf beiden Seiten: 3x = ②. Also ist x = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 39, 13]}, "h": "Der Faktor vor der Klammer wird mit jedem Summanden in der Klammer malgenommen.", "w": "5(x − 4) = 5x − 20. Dann 5x − 20 = 2x + 19. Subtrahiere 2x: 3x − 20 = 19. Addiere 20: 3x = 39. Teile durch 3: x = 13. Probe: 5 · 9 = 45 und 2 · 13 + 19 = 45.", "form": "lueckenweg", "zaehlt": "nein", "r": 15611}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim löst 3(2x − 5) − (x − 4) = 24 und gibt als Lösung x = ? an. Wie lautet sie?"}, "o": {"wert": 7}, "h": "Löse zuerst beide Klammern auf, achte auf das Minus vor der zweiten Klammer. Fasse dann zusammen.", "w": "3(2x − 5) = 6x − 15 und −(x − 4) = −x + 4. Links: 5x − 11 = 24. Addiere 11: 5x = 35. Teile durch 5: x = 7. Probe: 3 · 9 − 3 = 24.", "form": "anwenden", "zaehlt": "ja", "r": 15612}, {"l": "klammern", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Noa löst 5(x − 2) = 3x + 6: Zeile 1: Ausmultiplizieren: 5x − 2 = 3x + 6. Zeile 2: Subtrahiere ich 3x, bleibt 2x − 2 = 6. Zeile 3: Addiere ich 2, ist 2x = 8, also ist x = 4. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Wie oft wird die 5 beim Ausmultiplizieren verwendet? Prüfe die Klammer Summand für Summand.", "w": "Der Faktor 5 gilt für jeden Summanden in der Klammer: 5(x − 2) = 5x − 10. In Zeile 1 wurde die 2 nicht mit 5 malgenommen. Richtig: 5x − 10 = 3x + 6, daraus 2x = 16 und x = 8. Die Zeilen 2 und 3 rechnen mit dem falschen Ergebnis richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15613}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Kim behauptet, die Lösung von 4x − 9 = 2x + 13 ist x = 11. Setzt man 11 ein, so haben beide Seiten denselben Wert. Wie groß ist er?"}, "o": {"wert": 35}, "h": "Setze 11 für x ein: links und rechts. Beide Seiten müssen denselben Wert ergeben.", "w": "Links: 4 · 11 − 9 = 44 − 9 = 35. Rechts: 2 · 11 + 13 = 22 + 13 = 35. Beide Seiten sind 35, die Probe stimmt.", "form": "anwenden", "zaehlt": "ja", "r": 15614}, {"l": "probe", "t": "pruefen", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Welche dieser Zahlen ist Lösung der Gleichung 6x − 17 = 2x + 15? Prüfe durch Einsetzen."}, "a": ["x = 4", "x = 8", "x = 12"], "o": {"index": 1}, "h": "Setze jede Zahl links und rechts ein und vergleiche.", "w": "x = 8: links 6 · 8 − 17 = 31, rechts 2 · 8 + 15 = 31. Gleich, also ist 8 die Lösung. Bei 4 sind die Seiten 7 und 23, bei 12 sind sie 55 und 39.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15615}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Wie viele Lösungen hat die Gleichung 5(x + 2) − 3x = 2x + 13?"}, "a": ["genau eine Lösung", "keine Lösung", "unendlich viele Lösungen"], "o": {"index": 1}, "h": "Fasse beide Seiten zusammen. Was bleibt nach dem Subtrahieren von 2x übrig?", "w": "5(x + 2) − 3x = 5x + 10 − 3x = 2x + 10. Die Gleichung heißt 2x + 10 = 2x + 13. Subtrahiere 2x: 10 = 13. Das ist falsch, egal welche Zahl x ist: keine Lösung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15616}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Für welche Zahl k hat die Gleichung 5(x + 2) − 3x = 2x + k unendlich viele Lösungen?"}, "o": {"wert": 10}, "h": "Fasse die linke Seite zusammen. Wann stehen links und rechts dieselben Terme?", "w": "5(x + 2) − 3x = 2x + 10. Die Gleichung heißt 2x + 10 = 2x + k. Sie stimmt für jede Zahl x genau dann, wenn k = 10 ist.", "form": "umkehren", "zaehlt": "ja", "r": 15617}, {"l": "sonderfaelle", "t": "pruefen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex löst 6x − 4 = 2(3x + 5) − 1: Zeile 1: Rechts ausmultiplizieren und zusammenfassen: 2(3x + 5) − 1 = 6x + 9. Zeile 2: Subtrahiere ich 6x auf beiden Seiten, bleibt links −4 und rechts 9 stehen. Zeile 3: Diese Aussage stimmt nicht und enthält kein x mehr. Zeile 4: Also ist x = 0 die einzige Lösung. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Was bedeutet es, wenn nach dem Umformen eine falsche Aussage ohne x dasteht?", "w": "Eine falsche Aussage wie −4 = 9 gilt für jede Zahl x nicht. Die Gleichung hat deshalb keine Lösung. Zeile 4 ist falsch: x = 0 ergibt links −4 und rechts 9.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15618}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim startet in Passau mit dem Rad und fährt mit 18 km/h donauabwärts. Alex startet 2 Stunden später am selben Ort mit 27 km/h. Wie viele Stunden nach Alex' Start hat Alex Kim eingeholt?"}, "o": {"wert": 4, "einheit": "h"}, "h": "Beide haben bis zum Treffpunkt dieselbe Strecke zurückgelegt. Wie lange ist Kim unterwegs, wenn Alex x Stunden fährt?", "w": "Alex fährt x Stunden, Kim x + 2 Stunden. Gleiche Strecke: 27x = 18(x + 2). Ausmultiplizieren: 27x = 18x + 36. Subtrahiere 18x: 9x = 36. Also x = 4 Stunden.", "form": "anwenden", "zaehlt": "ja", "r": 15619}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In Oslo tauscht Kim Euro in Kronen. Die Wechselstube behält zuerst 3 € Gebühr ein und tauscht den Rest zum Kurs 1 € = 11,2 Kronen. Kim erhält 616 Kronen. Wie viele Euro hat Kim insgesamt abgegeben?"}, "o": {"wert": 58, "einheit": "€"}, "h": "Wie viele Euro wurden getauscht? Dazu kommt noch etwas.", "w": "Gleichung: (x − 3) · 11,2 = 616. Teile durch 11,2: x − 3 = 55. Addiere 3: x = 58. Probe: (58 − 3) · 11,2 = 616.", "form": "anwenden", "zaehlt": "ja", "r": 15620}, {"l": "sach", "t": "anwenden", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Sam plant ein rechteckiges Beet. Die Länge soll 4 m größer sein als die Breite. Der Zaun um das Beet ist 36 m lang. Wie breit ist das Beet?"}, "o": {"wert": 7, "einheit": "m"}, "h": "Wähle x für die Breite. Wie lang ist dann die Länge? Der Umfang ist zweimal Länge plus zweimal Breite.", "w": "Breite x, Länge x + 4. Umfang: 2x + 2(x + 4) = 36, also 4x + 8 = 36. Subtrahiere 8: 4x = 28. Teile durch 4: x = 7 m. Probe: 7 + 11 = 18 und 2 · 18 = 36.", "form": "umkehren", "zaehlt": "ja", "r": 15621}]$auf$::jsonb),
    (19, 'funktionen.quadratisch', 679, 14, $auf$[{"l": "scheitel", "t": "scheitel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Parabel y = 2(x − 5)² − 1 wird um 4 Einheiten nach rechts und um 7 Einheiten nach oben verschoben. Die neue Parabel hat den Scheitel S(①|②). Für x = 10 hat sie den y-Wert ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [9, 6, 8]}, "h": "Aus y = a(x − d)² + e liest du den Scheitel S(d|e) ab. Verschiebung nach rechts erhöht d, Verschiebung nach oben erhöht e.", "w": "Der alte Scheitel ist S(5|−1). Nach 4 nach rechts und 7 nach oben: S(9|6). Die neue Gleichung heißt y = 2(x − 9)² + 6. Für x = 10: y = 2 · 1 + 6 = 8.", "form": "lueckenweg", "zaehlt": "nein", "r": 15680}, {"l": "scheitel", "t": "scheitel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Gleichung gehört zu einer nach unten geöffneten Parabel mit dem Scheitel S(−4|9)?"}, "a": ["y = −(x − 4)² + 9", "y = (x + 4)² + 9", "y = −(x + 4)² − 9", "y = −(x + 4)² + 9"], "o": {"index": 3}, "h": "Setze den Scheitel in die Form y = a(x − d)² + e ein. Wann ist die Parabel nach unten geöffnet?", "w": "Die Scheitelform ist y = a(x − d)² + e mit d = −4 und e = 9, also (x − (−4))² = (x + 4)². Nach unten geöffnet heißt a < 0, hier a = −1. Die Gleichung heißt y = −(x + 4)² + 9.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15681}, {"l": "parameter", "t": "parameter", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Die Parabel y = a(x + 2)² − 5 geht durch den Punkt P(4|13). Wie groß ist a?"}, "o": {"wert": 0.5}, "h": "Setze die Koordinaten von P für x und y ein und löse nach a. Rechne erst (4 + 2)².", "w": "13 = a · (4 + 2)² − 5 = 36a − 5. Also 36a = 18 und a = 0,5. Probe: 0,5 · 36 − 5 = 13.", "form": "umkehren", "zaehlt": "ja", "r": 15682}, {"l": "spiegeln", "t": "spiegeln", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Spiegel steht senkrecht an der y-Achse. Die Bahn y = (x − 6)² + 4 erscheint darin gespiegelt. An welcher x-Stelle liegt der tiefste Punkt der Spiegelbahn?"}, "o": {"wert": -6}, "h": "Der tiefste Punkt der Bahn ist ihr Scheitel S(6|4). Was passiert mit dem x-Wert beim Spiegeln an der y-Achse?", "w": "Der Scheitel der Ausgangsparabel ist S(6|4). Spiegeln an der y-Achse wechselt das Vorzeichen der x-Koordinate: S'(−6|4). Die Spiegelbahn hat die Gleichung y = (x + 6)² + 4.", "form": "anwenden", "zaehlt": "ja", "r": 15683}, {"l": "spiegeln", "t": "spiegeln", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Die Wasseroberfläche (die x-Achse) spiegelt den Bogen y = 2(x − 3)² − 4. Welche Gleichung gehört zum Spiegelbild im Wasser?"}, "a": ["y = −2(x − 3)² − 4", "y = −2(x − 3)² + 4", "y = 2(x + 3)² − 4"], "o": {"index": 1}, "h": "Beim Spiegeln an der x-Achse wird jeder y-Wert zum Gegenwert. Prüfe einen Punkt, zum Beispiel x = 5.", "w": "Bei x = 5 hat die Parabel y = 2 · 4 − 4 = 4. Das Spiegelbild hat dort y = −4. Das passt zu −2(x − 3)² + 4: −2 · 4 + 4 = −4. Alle y-Werte kehren ihr Vorzeichen um, auch die −4.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15684}, {"l": "umformen", "t": "umformen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie lautet die y-Koordinate des Scheitels der Parabel y = x² + 12x + 50?"}, "o": {"wert": 14}, "h": "Ergänze quadratisch: Die Hälfte von 12 ist 6, ihr Quadrat 36. Wie ändert sich die Zahl hinten?", "w": "x² + 12x + 50 = (x² + 12x + 36) + 50 − 36 = (x + 6)² + 14. Der Scheitel ist S(−6|14), die y-Koordinate ist 14.", "form": "anwenden", "zaehlt": "ja", "r": 15685}, {"l": "umformen", "t": "umformen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Sam bringt y = x² − 10x + 19 in die Scheitelform: Zeile 1: Die Hälfte von 10 ist 5, deshalb steht (x − 5)² in der Klammer. Zeile 2: Es gilt (x − 5)² = x² − 10x + 25. Zeile 3: Also ist y = (x − 5)² + 19 und der Scheitel S(5|19). In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Setze x = 5 in die Ausgangsgleichung ein. Welchen y-Wert bekommst du?", "w": "Zeile 2 sagt, dass (x − 5)² um 25 größer ist als x² − 10x. Beim Übergang muss man die 25 wieder abziehen: y = (x − 5)² + 19 − 25 = (x − 5)² − 6. Der Scheitel ist S(5|−6). Probe: 25 − 50 + 19 = −6. Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15686}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Die Parabel y = x² − 6x − 55 hat zwei Nullstellen. Die kleinere ist ①. Die größere ist ②. Der Scheitel liegt genau in der Mitte bei x = ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [-5, 11, 3]}, "h": "Setze y = 0 und löse die Gleichung, zum Beispiel mit der Lösungsformel oder durch Zerlegen. Die Mitte ist der Mittelwert beider Nullstellen.", "w": "x² − 6x − 55 = (x − 11)(x + 5) = 0, also x = 11 oder x = −5. Der Scheitel liegt in der Mitte: (−5 + 11) : 2 = 3. Probe: 3² − 18 − 55 = −64 ist der kleinste y-Wert.", "form": "lueckenweg", "zaehlt": "nein", "r": 15687}, {"l": "nullstellen", "t": "nullstellen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Parabel y = (x + 2)² − 25 schneidet die x-Achse zweimal. Wie weit sind die beiden Schnittpunkte voneinander entfernt?"}, "o": {"wert": 10}, "h": "Setze y = 0 und löse nach x. Der Abstand ist der Unterschied der beiden Lösungen.", "w": "(x + 2)² = 25, also x + 2 = 5 oder x + 2 = −5. Die Nullstellen sind 3 und −7. Der Abstand ist 3 − (−7) = 10.", "form": "anwenden", "zaehlt": "ja", "r": 15688}, {"l": "punkte", "t": "punkte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Torbogen in Dubrovnik hat die Höhe h(x) = −0,02(x − 20)² + 9 (in Metern, x in Metern entlang der Straße). Wie hoch ist der Bogen bei x = 30?"}, "o": {"wert": 7, "einheit": "m"}, "h": "Setze x = 30 ein. Rechne erst die Klammer, dann das Quadrat, dann den Faktor −0,02.", "w": "h(30) = −0,02 · (30 − 20)² + 9 = −0,02 · 100 + 9 = −2 + 9 = 7. Der Bogen ist dort 7 m hoch.", "form": "anwenden", "zaehlt": "ja", "r": 15689}, {"l": "bestimmen", "t": "bestimmen", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Parabel y = x² + px + q geht durch die Punkte A(2|10) und B(4|32). Wie groß ist p?"}, "o": {"wert": 5}, "h": "Setze beide Punkte ein. Zwei Gleichungen mit p und q: Subtrahiere sie, dann fällt q weg.", "w": "A: 4 + 2p + q = 10. B: 16 + 4p + q = 32. B − A: 12 + 2p = 22, also p = 5. Dann ist q = 10 − 4 − 10 = −4.", "form": "umkehren", "zaehlt": "ja", "r": 15690}, {"l": "schnittpunkte", "t": "schnittpunkte", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Parabel y = x² − 4x + 1 und die Gerade y = 2x − 4 schneiden sich in zwei Punkten. Welche x-Koordinate hat der Schnittpunkt weiter rechts?"}, "o": {"wert": 5}, "h": "Setze die beiden Funktionsterme gleich und bringe alles auf eine Seite.", "w": "x² − 4x + 1 = 2x − 4 gibt x² − 6x + 5 = 0, also (x − 1)(x − 5) = 0. Die x-Koordinaten sind 1 und 5. Der rechte Schnittpunkt hat x = 5.", "form": "anwenden", "zaehlt": "ja", "r": 15691}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Ball fliegt nach h(t) = −5t² + 40t + 3 (Meter, t in Sekunden). Er ist nach ① Sekunden am höchsten, die größte Höhe ist ② Meter. Er steigt dabei um ③ Meter über die Starthöhe.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 83, 80]}, "h": "Der höchste Punkt ist der Scheitel. Bei y = at² + bt + c liegt er bei t = −b : (2a).", "w": "t = −40 : (2 · (−5)) = 4. h(4) = −5 · 16 + 160 + 3 = 83. Die Starthöhe ist h(0) = 3, der Ball steigt um 83 − 3 = 80 m.", "form": "lueckenweg", "zaehlt": "nein", "r": 15692}, {"l": "extremwert", "t": "extremwert", "p": "uebung", "s": 3, "g": "transfer", "y": "zahl", "f": {"text": "Sam zäunt am Campingplatz ein Rechteck ein, eine Längsseite liegt an einer Felswand und braucht keinen Zaun. Der Zaun ist 36 m lang. Wie viele Quadratmeter kann die Fläche höchstens haben?"}, "o": {"wert": 162, "einheit": "m²"}, "h": "Nenne die Breite x. Wie lang ist dann die Seite an der Wand? Die Fläche hängt dann von x ab.", "w": "Breite x, Länge 36 − 2x. Fläche A = x(36 − 2x) = −2x² + 36x. Der Scheitel liegt bei x = 36 : 4 = 9. A = 9 · 18 = 162 m².", "form": "anwenden", "zaehlt": "ja", "r": 15693}]$auf$::jsonb),
    (25, 'gleichungen.quadratisch', 579, 14, $auf$[{"l": "reinquadratisch", "t": "reinquadratisch", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du löst 2x² − 98 = 0. Es folgt x² = ①. ② ist die positive und ③ die negative Lösung.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [49, 7, -7]}, "h": "Addiere erst 98 auf beiden Seiten, teile dann durch 2. Zu x² = Zahl gehören zwei Lösungen mit entgegengesetztem Vorzeichen.", "w": "2x² = 98, also x² = 49. Die Lösungen sind 7 und −7, denn 7² = 49 und (−7)² = 49.", "form": "lueckenweg", "zaehlt": "nein", "r": 15580}, {"l": "reinquadratisch", "t": "reinquadratisch", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Gleichung 4x² − 196 = 0 hat zwei Lösungen. Wie lautet die negative Lösung?"}, "o": {"wert": -7}, "h": "Bringe zuerst das x² allein auf eine Seite. Welche Zahlen ergeben quadriert dieses Ergebnis?", "w": "4x² = 196, also x² = 49. Zwei Zahlen haben das Quadrat 49: 7 und −7. Die negative Lösung ist −7. Probe: 4 · 49 − 196 = 0.", "form": "anwenden", "zaehlt": "ja", "r": 15581}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche Lösungsmenge hat die Gleichung 4x² − 28x = 0?"}, "a": ["nur x = 7", "x = 0 oder x = 7", "x = 7 oder x = −7", "x = 0 oder x = 28"], "o": {"index": 1}, "h": "Klammere x aus. Ein Produkt ist null, wenn einer der Faktoren null ist.", "w": "4x² − 28x = 4x · (x − 7) = 0. Ein Faktor muss null sein: 4x = 0 gibt x = 0, x − 7 = 0 gibt x = 7. Beide Zahlen erfüllen die Gleichung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15582}, {"l": "ausklammern", "t": "ausklammern", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Sam löst 6x² = 18x: Zeile 1: Ich bringe alles auf eine Seite: 6x² − 18x = 0. Zeile 2: Ich klammere 6x aus: 6x(x − 3) = 0. Zeile 3: Ein Produkt ist null, wenn ein Faktor null ist, also muss hier nur der Faktor x − 3 null sein. Zeile 4: Die Gleichung hat deshalb nur die Lösung x = 3. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Das Produkt 6x(x − 3) hat zwei Faktoren. Wann ist der erste Faktor null?", "w": "Beim Nullprodukt kann jeder Faktor null sein: 6x = 0 gibt x = 0, und x − 3 = 0 gibt x = 3. Sam hat den Faktor 6x übersehen. Probe: Für x = 0 gilt 6 · 0 = 18 · 0. Die Lösungen sind x = 0 und x = 3. Der Fehler steckt in Zeile 3, Zeile 4 folgt daraus.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15583}, {"l": "faktorisieren", "t": "faktorisieren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse x² − 4x − 21 = 0. Wie lautet die größere Lösung?"}, "o": {"wert": 7}, "h": "Suche zwei Zahlen mit dem Produkt −21 und der Summe −4. Dann zerlege in zwei Klammern.", "w": "x² − 4x − 21 = (x − 7)(x + 3) = 0. Ein Faktor muss null sein: x = 7 oder x = −3. Die größere Lösung ist 7.", "form": "anwenden", "zaehlt": "ja", "r": 15584}, {"l": "faktorisieren", "t": "faktorisieren", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Wasserrutsche folgt der Linie y = x² + px + q (Meter). Sie liegt bei den Stellen 4 und −9 auf Höhe null. Welchen Wert hat q?"}, "o": {"wert": -36}, "h": "Schreibe die Gleichung als Produkt (x − Lösung) · (x − Lösung) = 0 und multipliziere aus.", "w": "Es gilt (x − 4)(x + 9) = x² + 5x − 36. Also ist p = 5 und q = −36. Probe: 4² + 5 · 4 − 36 = 0.", "form": "umkehren", "zaehlt": "ja", "r": 15585}, {"l": "ergaenzung", "t": "ergaenzung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Mit der quadratischen Ergänzung wird x² + 10x + 9 = 0 zu (x + 5)² = b. Wie groß ist b?"}, "o": {"wert": 16}, "h": "Ergänze die Hälfte von 10 zum Quadrat auf beiden Seiten, die 9 gehört danach auf die andere Seite.", "w": "Die Hälfte von 10 ist 5, ihr Quadrat 25. x² + 10x + 25 = 25 − 9, also (x + 5)² = 16. Die Lösungen sind x = −1 und x = −9.", "form": "anwenden", "zaehlt": "ja", "r": 15586}, {"l": "loesungsformel", "t": "loesungsformel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Für 3x² − 24x + 21 = 0 gilt a = 3, b = −24, c = 21. Die Diskriminante b² − 4ac ist ①. Ihre Wurzel ist ②. Die größere Lösung x = (24 + ②) : 6 ist ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [324, 18, 7]}, "h": "Rechne b² zuerst (576), dann 4 · a · c, dann die Differenz. Beachte: Punkt vor Strich.", "w": "b² = 576, 4ac = 4 · 3 · 21 = 252, also 576 − 252 = 324. √324 = 18. Die größere Lösung ist (24 + 18) : 6 = 7. Die andere ist (24 − 18) : 6 = 1.", "form": "lueckenweg", "zaehlt": "nein", "r": 15587}, {"l": "loesungsformel", "t": "loesungsformel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Löse 2x² + 3x − 20 = 0 mit der Lösungsformel. Wie lautet die negative Lösung?"}, "o": {"wert": -4}, "h": "Berechne zuerst die Diskriminante b² − 4ac. Beachte, dass c negativ ist.", "w": "D = 3² − 4 · 2 · (−20) = 9 + 160 = 169, √169 = 13. x = (−3 ± 13) : 4. Die Lösungen sind 2,5 und −4. Die negative Lösung ist −4.", "form": "anwenden", "zaehlt": "ja", "r": 15588}, {"l": "bruchgleichung", "t": "bruchgleichung", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Für x ≠ 0 gilt die Gleichung 40 : x = x − 6. Wie lautet die positive Lösung?"}, "o": {"wert": 10}, "h": "Multipliziere beide Seiten mit x, damit der Bruch verschwindet. Bringe dann alles auf eine Seite.", "w": "Mit x multiplizieren: 40 = x² − 6x, also x² − 6x − 40 = 0. Das ist (x − 10)(x + 4) = 0, also x = 10 oder x = −4. Die positive Lösung ist 10. Probe: 40 : 10 = 4 und 10 − 6 = 4.", "form": "anwenden", "zaehlt": "ja", "r": 15589}, {"l": "diskriminante", "t": "diskriminante", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Für welchen positiven Wert von k hat die Gleichung 3x² + kx + 27 = 0 genau eine Lösung?"}, "o": {"wert": 18}, "h": "Genau eine Lösung gibt es, wenn die Diskriminante k² − 4 · 3 · 27 gleich null ist.", "w": "D = k² − 4 · 3 · 27 = k² − 324. D = 0 gilt für k² = 324, also k = 18 (oder −18). Der positive Wert ist 18. Dann ist 3x² + 18x + 27 = 3(x + 3)² = 0 mit der einzigen Lösung −3.", "form": "umkehren", "zaehlt": "ja", "r": 15590}, {"l": "diskriminante", "t": "diskriminante", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Wie viele gemeinsame Punkte hat die Parabel y = 2x² + 3x + 5 mit der x-Achse?"}, "a": ["zwei", "keinen", "genau einen"], "o": {"index": 1}, "h": "Setze y = 0. Berechne die Diskriminante b² − 4ac und vergleiche sie mit 0.", "w": "2x² + 3x + 5 = 0 hat D = 3² − 4 · 2 · 5 = 9 − 40 = −31. Die Diskriminante ist negativ, also gibt es keinen Schnittpunkt.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15591}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Stein wird vom Rand einer Klippe in Kroatien nach oben geworfen. Seine Höhe über dem Meer ist h(t) = −5t² + 20t + 25 in Metern, t in Sekunden. Nach wie vielen Sekunden trifft er auf das Wasser (h = 0)?"}, "o": {"wert": 5, "einheit": "s"}, "h": "Setze h(t) = 0. Teile durch −5, damit vor t² die 1 steht. Prüfe, welche Lösung zur Frage passt.", "w": "−5t² + 20t + 25 = 0 | : (−5) gibt t² − 4t − 5 = 0, also (t − 5)(t + 1) = 0. Es folgt t = 5 oder t = −1. Negative Zeit passt nicht, also nach 5 Sekunden.", "form": "anwenden", "zaehlt": "ja", "r": 15592}, {"l": "sachaufgabe", "t": "sachaufgabe", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein rechteckiger Campingplatz am Gardasee ist 9 m länger als breit und 360 m² groß. Wie breit ist er?"}, "o": {"wert": 15, "einheit": "m"}, "h": "Nenne die Breite x. Wie groß ist dann die Länge? Stelle eine Gleichung für die Fläche auf.", "w": "Länge x + 9, Fläche x(x + 9) = 360. Also x² + 9x − 360 = 0. Diskriminante: 81 + 1440 = 1521 = 39². x = (−9 + 39) : 2 = 15. Die andere Lösung −24 passt nicht. Probe: 15 · 24 = 360.", "form": "anwenden", "zaehlt": "ja", "r": 15593}]$auf$::jsonb),
    (33, 'stochastik.verknuepft', 748, 15, $auf$[{"l": "elemente", "t": "elemente", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim schreibt alle Quadratzahlen auf, die größer als 70 und kleiner als 700 sind, und bildet daraus eine Menge. Wie viele Elemente hat die Menge?"}, "o": {"wert": 18}, "h": "Suche die kleinste und die größte Quadratzahl in diesem Bereich. Welche Zahlen werden dafür quadriert, und wie viele sind das?", "w": "8² = 64 liegt noch unter 70, 9² = 81 ist die erste Quadratzahl im Bereich. 26² = 676 ist die letzte, denn 27² = 729 ist größer als 700. Es sind die Quadrate der Zahlen 9 bis 26: 26 − 9 + 1 = 18 Elemente.", "form": "anwenden", "zaehlt": "ja", "r": 15749}, {"l": "schnitt", "t": "schnitt", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "A ist die Menge aller Teiler von 60, B die Menge aller Teiler von 45. Wie viele Elemente liegen in A, aber nicht in B?"}, "o": {"wert": 8}, "h": "Schreibe beide Teilermengen auf. Welche Zahlen kommen in beiden vor (Schnitt A ∩ B)? Diese gehören nicht zur gesuchten Menge.", "w": "Die Teiler von 60 sind 1, 2, 3, 4, 5, 6, 10, 12, 15, 20, 30, 60 (12 Elemente). Die Teiler von 45 sind 1, 3, 5, 9, 15, 45. In beiden stehen 1, 3, 5 und 15, das sind 4 Elemente. In A, aber nicht in B liegen 12 − 4 = 8 Elemente.", "form": "anwenden", "zaehlt": "ja", "r": 15750}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "A ist die Menge der Vielfachen von 6 zwischen 1 und 60 (60 eingeschlossen), B die Menge der Vielfachen von 4 zwischen 1 und 60 (60 eingeschlossen). Wie viele Elemente hat die Vereinigung A ∪ B?"}, "o": {"wert": 20}, "h": "Zähle erst A und B, dann die Zahlen, die in beiden stehen. Welche Zahlen sind das?", "w": "A hat 10 Elemente (6, 12, …, 60), B hat 15 Elemente (4, 8, …, 60). In beiden stehen die Vielfachen von 12: 12, 24, 36, 48, 60, das sind 5. Vereinigung: 10 + 15 − 5 = 20.", "form": "anwenden", "zaehlt": "ja", "r": 15751}, {"l": "verknuepfen", "t": "verknuepfen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Von den Besuchern einer Therme sind 55 % Frauen, 44 % nutzen die Sauna, und 33 % sind Frauen, die die Sauna nutzen. Wie viel Prozent aller Besucher sind weder Frau noch nutzen die Sauna?"}, "o": {"wert": 34, "einheit": "%"}, "h": "Die Besucher, die Frau sind oder die Sauna nutzen, bilden die Vereinigung. Wer beides ist, darf nur einmal zählen. Wie viel bleibt vom Ganzen übrig?", "w": "Frau oder Sauna: 55 + 44 − 33 = 66 (die 33 stehen in beiden Zahlen). Weder noch ist das Gegenteil: 100 − 66 = 34. Es sind 34 % aller Besucher.", "form": "anwenden", "zaehlt": "ja", "r": 15752}, {"l": "additionssatz", "t": "additionssatz", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einer Reisegruppe von 40 Personen haben 24 Sonnencreme dabei, 18 einen Hut und 10 beides. Mindestens eines von beiden haben ① Personen. Keines von beiden haben ② Personen. Das sind ③ Prozent der Gruppe.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [32, 8, 20]}, "h": "Wer beides hat, steht in beiden Zahlen 24 und 18. Wie oft darf man ihn zählen?", "w": "Mindestens eines: 24 + 18 − 10 = 32. Keines: 40 − 32 = 8. Anteil: 8 : 40 = 0,2 = 20 %.", "form": "lueckenweg", "zaehlt": "nein", "r": 15753}, {"l": "additionssatz", "t": "additionssatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "In einem Reisebüro gewinnt man mit Wahrscheinlichkeit 0,35 einen Hotelgutschein (A) und mit 0,28 einen Flugrabatt (B). Mit Wahrscheinlichkeit 0,09 gewinnt man beides. Wie groß ist die Wahrscheinlichkeit, mindestens einen der beiden Preise zu gewinnen?"}, "o": {"wert": 0.54}, "h": "Wer beides gewinnt, ist in beiden Wahrscheinlichkeiten enthalten. Wie oft soll er zählen?", "w": "P(A ∪ B) = P(A) + P(B) − P(A ∩ B) = 0,35 + 0,28 − 0,09 = 0,54.", "form": "anwenden", "zaehlt": "ja", "r": 15754}, {"l": "additionssatz", "t": "additionssatz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Bei einer Verlosung gewinnt man mit Wahrscheinlichkeit 0,42 einen Hotelgutschein (A) und mit 0,35 einen Flugrabatt (B). Mit Wahrscheinlichkeit 0,61 gewinnt man mindestens einen der beiden Preise. Wie groß ist die Wahrscheinlichkeit, beide Preise zu gewinnen?"}, "o": {"wert": 0.16}, "h": "Der Additionssatz gilt auch rückwärts: P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Stelle nach P(A ∩ B) um.", "w": "Aus P(A ∪ B) = P(A) + P(B) − P(A ∩ B) folgt P(A ∩ B) = P(A) + P(B) − P(A ∪ B) = 0,42 + 0,35 − 0,61 = 0,16.", "form": "umkehren", "zaehlt": "ja", "r": 15755}, {"l": "venn", "t": "venn", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Im Venn-Diagramm liegen von 25 Elementen 14 in A, 11 in B und 6 in beiden. Wie viele Elemente liegen in genau einer der beiden Mengen?"}, "o": {"wert": 13}, "h": "Trenne jede Menge in den Teil, der nur ihr gehört, und den Teil im Schnitt.", "w": "Nur in A: 14 − 6 = 8. Nur in B: 11 − 6 = 5. Genau eine Menge: 8 + 5 = 13.", "form": "anwenden", "zaehlt": "ja", "r": 15756}, {"l": "venn", "t": "venn", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf einem Campingplatz leihen 52 % der Gäste ein Fahrrad, 31 % ein Kajak und 18 % beides. Wie viel Prozent aller Gäste leihen genau eines der beiden Geräte?"}, "o": {"wert": 47, "einheit": "%"}, "h": "Wer beides leiht, soll nicht zählen. Trenne: nur Fahrrad, nur Kajak. Wie viel vom Fahrrad-Anteil gehört auch zum Kajak-Anteil?", "w": "Nur Fahrrad: 52 − 18 = 34. Nur Kajak: 31 − 18 = 13. Genau eines: 34 + 13 = 47. Es sind 47 % aller Gäste.", "form": "anwenden", "zaehlt": "ja", "r": 15757}, {"l": "mengen_verstehen", "t": "mengen_verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Es gilt A ⊆ B: Jedes Element von A liegt auch in B. Welche Aussage über die Schnittmenge und die Vereinigung gilt immer?"}, "a": ["A ∩ B = B und A ∪ B = A", "A ∩ B = ∅ und A ∪ B = B", "A ∩ B = A und A ∪ B = B", "A ∩ B = A und A ∪ B = A"], "o": {"index": 2}, "h": "Wähle selbst ein Beispiel: A = {2, 4} und B = {1, 2, 3, 4}. Bestimme beide Mengen.", "w": "Im Beispiel A = {2, 4} und B = {1, 2, 3, 4} gilt A ∩ B = {2, 4} = A und A ∪ B = {1, 2, 3, 4} = B. Das gilt allgemein: Was in A liegt, liegt auch in B.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15758}, {"l": "vierfeld", "t": "vierfeld", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einem Skiort sind 100 Gäste. Davon sind 64 Frauen, 41 fahren Ski, und 27 Frauen fahren Ski. Frauen ohne Ski gibt es ①. Männer mit Ski gibt es ②. Männer ohne Ski gibt es ③.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [37, 14, 22]}, "h": "Trage die Zahlen in eine Vierfeldertafel ein. Jede Zeile und jede Spalte ergibt die angegebene Summe.", "w": "Frauen ohne Ski: 64 − 27 = 37. Männer mit Ski: 41 − 27 = 14. Männer insgesamt: 100 − 64 = 36, davon 14 mit Ski, also 36 − 14 = 22 ohne Ski.", "form": "lueckenweg", "zaehlt": "nein", "r": 15759}, {"l": "vierfeld", "t": "vierfeld", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Von 120 Reisenden sind 72 Frauen. 47 Reisende fahren Rad, davon sind 19 Männer. Wie viele Frauen fahren nicht Rad?"}, "o": {"wert": 44}, "h": "Zeichne eine Vierfeldertafel mit Frau/Mann und Rad/nicht Rad. Beginne mit den Radfahrern.", "w": "Frauen mit Rad: 47 − 19 = 28. Frauen insgesamt 72, also Frauen ohne Rad: 72 − 28 = 44.", "form": "anwenden", "zaehlt": "ja", "r": 15760}, {"l": "tafel_wkeit", "t": "tafel_wkeit", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Bei Gästen eines Hotels gilt: Mit Wahrscheinlichkeit 0,6 ist ein Gast eine Frau, mit 0,45 fährt er Ski, und mit 0,27 ist er eine Frau, die Ski fährt. Wie groß ist die Wahrscheinlichkeit, dass ein Gast ein Mann ist, der nicht Ski fährt?"}, "o": {"wert": 0.22}, "h": "Fülle eine Vierfeldertafel mit Wahrscheinlichkeiten. Männer ohne Ski ist das letzte Feld.", "w": "Mann: 1 − 0,6 = 0,4. Mann und Ski: 0,45 − 0,27 = 0,18. Mann ohne Ski: 0,4 − 0,18 = 0,22.", "form": "anwenden", "zaehlt": "ja", "r": 15761}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Für zwei Ereignisse A und B gilt P(A ∪ B) = P(A) + P(B). Was folgt daraus?"}, "a": ["A liegt ganz in B (A ⊆ B).", "Der Schnitt hat die Wahrscheinlichkeit 0: P(A ∩ B) = 0.", "A und B sind gleich wahrscheinlich."], "o": {"index": 1}, "h": "Vergleiche mit dem Additionssatz P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Was muss P(A ∩ B) sein, damit beide Gleichungen stimmen?", "w": "Der Additionssatz lautet P(A ∪ B) = P(A) + P(B) − P(A ∩ B). Soll P(A ∪ B) = P(A) + P(B) gelten, muss P(A ∩ B) = 0 sein. Mehr folgt aus der Gleichung allein nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15762}, {"l": "verstehen", "t": "verstehen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex untersucht die Gäste eines Skiorts: 40 % fahren Ski (A), 30 % sind Kinder (B), und 12 % sind Kinder, die Ski fahren. Er schreibt: Zeile 1: Es gilt P(A ∩ B) = 0,12. Zeile 2: Gäste, die Ski fahren und keine Kinder sind: 0,40 − 0,12 = 0,28. Zeile 3: Man addiert die beiden Wahrscheinlichkeiten, also ist die Wahrscheinlichkeit für Ski oder Kind P(A ∪ B) = 0,70. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie oft werden die Kinder, die Ski fahren, in 0,40 + 0,30 gezählt? Wie oft sollen sie in der Vereinigung zählen?", "w": "Die Kinder, die Ski fahren, stecken in 0,40 und in 0,30, sie werden also doppelt gezählt. Der Additionssatz zieht den Schnitt ab: P(A ∪ B) = 0,40 + 0,30 − 0,12 = 0,58. Die Zeilen 1 und 2 sind richtig. Der Fehler steckt in Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15763}]$auf$::jsonb),
    (37, 'trigo.pythagoras', 555, 12, $auf$[{"l": "hypotenuse", "t": "hypotenuse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein rechtwinkliges Dreieck hat die Katheten 9 cm und 40 cm. Die Summe der Kathetenquadrate ist ①. Die Hypotenuse ist ② cm lang. Der Umfang des Dreiecks ist ③ cm.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [1681, 41, 90]}, "h": "Im rechtwinkligen Dreieck gilt: Kathete im Quadrat plus Kathete im Quadrat ist Hypotenuse im Quadrat.", "w": "9² = 81 und 40² = 1600, die Summe ist 1681. Weil 41 · 41 = 1681 gilt, ist die Hypotenuse 41 cm lang. Umfang: 9 + 40 + 41 = 90 cm.", "form": "lueckenweg", "zaehlt": "nein", "r": 15556}, {"l": "hypotenuse", "t": "hypotenuse", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Seilbahn überwindet einen waagerechten Abstand von 1,2 km und einen Höhenunterschied von 0,5 km. Wie lang ist das Seil in Kilometern, wenn man es als gerade Strecke ansieht?"}, "o": {"wert": 1.3, "einheit": "km"}, "h": "Waagerechter Abstand, Höhenunterschied und Seil bilden ein rechtwinkliges Dreieck. Welche Seite ist die längste?", "w": "Das Seil ist die Hypotenuse: 1,2² + 0,5² = 1,44 + 0,25 = 1,69. Die Wurzel aus 1,69 ist 1,3, denn 1,3 · 1,3 = 1,69. Das Seil ist 1,3 km lang.", "form": "anwenden", "zaehlt": "ja", "r": 15557}, {"l": "kathete", "t": "kathete", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein 61 m langes Stahlseil spannt von der Spitze eines senkrechten Funkmasts zu einem Punkt am Boden, der 11 m vom Fuß des Masts entfernt ist. Wie hoch ist der Mast in Metern?"}, "o": {"wert": 60, "einheit": "m"}, "h": "Das Seil ist die längste Seite im Dreieck. Welche Seite suchst du, und wie rechnest du dann?", "w": "Das Seil ist die Hypotenuse (61 m), der Abstand 11 m eine Kathete, der Mast die andere. h² = 61² − 11² = 3721 − 121 = 3600, also h = 60 m.", "form": "anwenden", "zaehlt": "ja", "r": 15558}, {"l": "kathete", "t": "kathete", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein rechtwinkliges Dreieck hat die Hypotenuse c = 17 cm und die Kathete a = 8 cm. Welche Gleichung liefert die zweite Kathete b?"}, "a": ["b² = 17² − 8²", "b² = 17² + 8²", "b = 17 − 8"], "o": {"index": 0}, "h": "Welche der drei Seiten ist die längste? Sie steht auf der anderen Seite der Gleichung a² + b² = c².", "w": "Nach dem Satz des Pythagoras gilt a² + b² = c². Umgestellt: b² = c² − a² = 289 − 64 = 225. Also ist b = 15 cm.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15559}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Welches Dreieck mit den angegebenen Seitenlängen (in cm) ist rechtwinklig?"}, "a": ["7, 24, 26", "9, 12, 16", "8, 15, 17"], "o": {"index": 2}, "h": "Quadriere die zwei kürzeren Seiten, addiere und vergleiche mit dem Quadrat der längsten Seite.", "w": "8² + 15² = 64 + 225 = 289 = 17². Dann ist das Dreieck nach der Umkehrung des Satzes des Pythagoras rechtwinklig. Bei 7, 24, 26 ist 625 ≠ 676, bei 9, 12, 16 ist 225 ≠ 256.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15560}, {"l": "umkehrung", "t": "umkehrung", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dreieck hat die Seiten 39 cm, 89 cm und x cm, wobei 89 cm die längste Seite ist. Für welche Zahl x ist es rechtwinklig?"}, "o": {"wert": 80, "einheit": "cm"}, "h": "Die längste Seite ist die Hypotenuse. Wie lautet die Gleichung, wenn x eine Kathete ist?", "w": "x² + 39² = 89², also x² = 7921 − 1521 = 6400. Weil 80 · 80 = 6400 ist, gilt x = 80. Das Dreieck mit 39, 80, 89 ist rechtwinklig.", "form": "umkehren", "zaehlt": "ja", "r": 15561}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Im Koordinatensystem liegen die Punkte A(−2|3) und B(4|11). Wie lang ist die Strecke [AB]?"}, "o": {"wert": 10, "einheit": "LE"}, "h": "Zeichne ein rechtwinkliges Dreieck mit [AB] als Hypotenuse. Wie lang sind die beiden Katheten?", "w": "Waagerechter Unterschied: 4 − (−2) = 6. Senkrechter Unterschied: 11 − 3 = 8. AB² = 6² + 8² = 36 + 64 = 100, also AB = 10.", "form": "anwenden", "zaehlt": "ja", "r": 15562}, {"l": "koordinaten", "t": "koordinaten", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Der Punkt P(x|7) mit x > 0 hat von A(0|1) den Abstand 10. Welchen Wert hat x?"}, "o": {"wert": 8}, "h": "Zeichne die Strecke [AP] als Hypotenuse. Der senkrechte Unterschied ist eine Kathete, der waagerechte Unterschied x die andere.", "w": "Senkrechter Unterschied: 7 − 1 = 6. Es gilt x² + 6² = 10², also x² = 100 − 36 = 64 und x = 8.", "form": "umkehren", "zaehlt": "ja", "r": 15563}, {"l": "raum", "t": "raum", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein Quader hat die Kanten 12 cm, 16 cm und 15 cm. Die Diagonale der Grundfläche (12 cm und 16 cm) ist ① cm lang. Die Raumdiagonale ist ② cm lang. Sie ist ③ cm länger als die Diagonale der Grundfläche.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [20, 25, 5]}, "h": "Die Diagonale der Grundfläche ist eine Kathete in einem zweiten rechtwinkligen Dreieck mit der Höhe 15 cm.", "w": "d² = 144 + 256 = 400, also d = 20. D² = 20² + 15² = 400 + 225 = 625, also D = 25. Unterschied: 25 − 20 = 5.", "form": "lueckenweg", "zaehlt": "nein", "r": 15564}, {"l": "raum", "t": "raum", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Koffer ist 8 dm lang, 9 dm breit und 12 dm hoch. Wie lang ist der längste gerade Stab, der hineinpasst (Raumdiagonale)?"}, "o": {"wert": 17, "einheit": "dm"}, "h": "Rechne zuerst die Diagonale der Grundfläche. Sie ist eine Kathete in einem zweiten rechtwinkligen Dreieck.", "w": "Grundfläche (8 und 9): d² = 64 + 81 = 145. Raumdiagonale: D² = 145 + 12² = 145 + 144 = 289. D = 17 dm.", "form": "anwenden", "zaehlt": "ja", "r": 15565}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Zelt hat zwei gleiche rechteckige Dachflächen. Es ist am Boden 4 m breit, der First ist 1,5 m hoch, und die Dachflächen sind 6 m lang. Wie viele Quadratmeter Stoff haben die beiden Dachflächen zusammen?"}, "o": {"wert": 30, "einheit": "m²"}, "h": "Die Breite einer Dachfläche ist die Schräge im Querschnitt. Der Querschnitt ist ein gleichschenkliges Dreieck: Zerlege es in zwei rechtwinklige.", "w": "Halbe Breite 2 m, Höhe 1,5 m. Schräge: s² = 2² + 1,5² = 4 + 2,25 = 6,25, also s = 2,5 m. Eine Dachfläche: 2,5 · 6 = 15 m². Zwei: 30 m².", "form": "anwenden", "zaehlt": "ja", "r": 15566}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex berechnet die Höhe eines gleichschenkligen Dreiecks mit der Basis 10 cm und den Schenkeln 13 cm: Zeile 1: Die Höhe halbiert die Basis, die halbe Basis ist 5 cm lang. Zeile 2: Höhe, halbe Basis und Schenkel bilden ein rechtwinkliges Dreieck, der Schenkel ist die Hypotenuse. Zeile 3: Daraus folgt h² = 13² + 5², also ist h² größer als 169. Zeile 4: Die Höhe ist deshalb etwa 14 cm lang. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Welche Seite ist im kleinen rechtwinkligen Dreieck die längste? Wie lautet dann die Gleichung?", "w": "Weil der Schenkel die Hypotenuse ist, gilt h² + 5² = 13², also h² = 169 − 25 = 144 und h = 12 cm. In Zeile 3 wurde die Hypotenuse wie eine Kathete addiert. Zeile 4 folgt aus dem falschen Wert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15567}]$auf$::jsonb),
    (38, 'trigo.rechtwinklig', 597, 13, $auf$[{"l": "seiten", "t": "seiten", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Im Dreieck ABC liegt der rechte Winkel bei C. Welche Seite ist die Gegenkathete des Winkels α bei A?"}, "a": ["b (die Seite AC)", "c (die Seite AB)", "a (die Seite BC)"], "o": {"index": 2}, "h": "Die Gegenkathete liegt dem Winkel gegenüber, ohne ihn zu berühren.", "w": "Bei A liegt der Winkel α. Gegenüber von A liegt die Seite a = BC. Sie berührt A nicht und ist keine Hypotenuse. Also ist a die Gegenkathete von α.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15598}, {"l": "seiten", "t": "seiten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Im Dreieck ABC liegt der rechte Winkel bei C. Welche Seite ist zugleich Gegenkathete von β (bei B) und Ankathete von α (bei A)?"}, "a": ["b (die Seite AC)", "a (die Seite BC)", "c (die Seite AB)"], "o": {"index": 0}, "h": "Zeichne das Dreieck. Welche Seite liegt gegenüber von B? Berührt diese Seite A?", "w": "Gegenüber von B liegt die Seite b = AC. Sie berührt A, ist also Ankathete von α. Damit ist b Gegenkathete von β und Ankathete von α.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15599}, {"l": "verhaeltnisse", "t": "verhaeltnisse", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einem rechtwinkligen Dreieck ist die Hypotenuse 35 cm lang, es gilt sin α = 0,6 und cos α = 0,8. Die Gegenkathete von α ist ① cm lang. Die Ankathete von α ist ② cm lang. Der Umfang des Dreiecks ist ③ cm.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [21, 28, 84]}, "h": "Der Sinus ist Gegenkathete durch Hypotenuse, der Kosinus ist Ankathete durch Hypotenuse. Stelle um.", "w": "Gegenkathete = sin α · Hypotenuse = 0,6 · 35 = 21. Ankathete = cos α · Hypotenuse = 0,8 · 35 = 28. Umfang: 35 + 21 + 28 = 84. Probe: 21² + 28² = 441 + 784 = 1225 = 35².", "form": "lueckenweg", "zaehlt": "nein", "r": 15600}, {"l": "verhaeltnisse", "t": "verhaeltnisse", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Hang bildet mit der Waagerechten einen Winkel α mit tan α = 0,75. Die Strecke waagerecht gemessen ist 32 m lang. Wie hoch liegt der Hangpunkt über dem Ausgangspunkt?"}, "o": {"wert": 24, "einheit": "m"}, "h": "Der Tangens ist Gegenkathete durch Ankathete. Welche Seite ist die Waagerechte, welche die Höhe?", "w": "tan α = Gegenkathete : Ankathete. Die Höhe ist die Gegenkathete: 0,75 · 32 = 24 m.", "form": "anwenden", "zaehlt": "ja", "r": 15601}, {"l": "seite", "t": "seite", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Seilbahn steigt unter einem Winkel von 28° zur Waagerechten an. Waagerecht gemessen legt sie 1,5 km zurück. Welchen Höhenunterschied überwindet sie? Runde erst das Endergebnis auf zwei Dezimalstellen."}, "o": {"wert": 0.8, "einheit": "km"}, "h": "Die waagerechte Strecke ist die Ankathete des Winkels, der Höhenunterschied die Gegenkathete. Welches Verhältnis verbindet beide?", "w": "tan 28° = Höhe : 1,5 km, also Höhe = 1,5 · tan 28° ≈ 1,5 · 0,5317 ≈ 0,80 km.", "form": "anwenden", "zaehlt": "ja", "r": 15602}, {"l": "seite", "t": "seite", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Eine Rampe soll einen Höhenunterschied von 0,9 m überwinden und mit der Waagerechten einen Winkel von 12° bilden. Wie lang ist die Rampe (die schräge Strecke)? Runde erst das Endergebnis auf zwei Dezimalstellen."}, "o": {"wert": 4.33, "einheit": "m"}, "h": "Die Höhe ist die Gegenkathete des Winkels, die Rampe die Hypotenuse. Welches Verhältnis passt?", "w": "sin 12° = 0,9 : Länge, also Länge = 0,9 : sin 12° ≈ 0,9 : 0,2079 ≈ 4,33 m.", "form": "umkehren", "zaehlt": "ja", "r": 15603}, {"l": "winkel", "t": "winkel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Treppenstufe ist 15 cm hoch und 28 cm tief. Unter welchem Winkel zur Waagerechten steigt die Treppe an? Runde erst das Endergebnis auf eine Dezimalstelle (in Grad)."}, "o": {"wert": 28.2, "einheit": "°"}, "h": "Stufenhöhe und Stufentiefe sind die Katheten. Welches Verhältnis kennst du, und wie kommst du von ihm zum Winkel?", "w": "tan α = 15 : 28 ≈ 0,5357. Mit der Umkehrfunktion des Tangens: α ≈ 28,2°.", "form": "anwenden", "zaehlt": "ja", "r": 15604}, {"l": "beziehungen", "t": "beziehungen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein spitzer Winkel α hat sin α = 0,28. Wie groß ist cos α?"}, "o": {"wert": 0.96}, "h": "Für jeden spitzen Winkel gilt (sin α)² + (cos α)² = 1. Stelle um und ziehe die Wurzel.", "w": "(cos α)² = 1 − 0,28² = 1 − 0,0784 = 0,9216. Die Wurzel ist 0,96. Probe: 0,96² = 0,9216.", "form": "anwenden", "zaehlt": "ja", "r": 15605}, {"l": "beziehungen", "t": "beziehungen", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Es gilt sin 70° ≈ 0,9397. Für welchen spitzen Winkel hat der Kosinus denselben Wert?"}, "a": ["für 20°", "für 70°", "für 45°", "für 50°"], "o": {"index": 0}, "h": "In einem rechtwinkligen Dreieck ist die Gegenkathete des einen spitzen Winkels die Ankathete des anderen. Die beiden spitzen Winkel ergeben zusammen 90°.", "w": "Die beiden spitzen Winkel eines rechtwinkligen Dreiecks ergänzen sich zu 90°. Es gilt sin α = cos(90° − α). Mit α = 70° folgt sin 70° = cos 20°.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15606}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Vom Leuchtturm in Kroatien, dessen Spitze 38 m über dem Meer liegt, sieht man ein Boot unter einem Tiefenwinkel von 4°. Der Fuß des Leuchtturms liegt auf Meereshöhe. Wie weit ist das Boot waagerecht vom Fuß des Leuchtturms entfernt? Runde erst das Endergebnis auf ganze Meter."}, "o": {"wert": 543, "einheit": "m"}, "h": "Der Tiefenwinkel ist genauso groß wie der Winkel am Boot im Dreieck. Welche Seiten sind bekannt, welche gesucht?", "w": "Im rechtwinkligen Dreieck gilt tan 4° = 38 : Entfernung. Also Entfernung = 38 : tan 4° ≈ 38 : 0,06993 ≈ 543 m.", "form": "anwenden", "zaehlt": "ja", "r": 15607}, {"l": "anwendung", "t": "anwendung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex berechnet im rechtwinkligen Dreieck (Hypotenuse 20 cm, α = 40°) die Ankathete von α: Zeile 1: Die Ankathete liegt am Winkel an, deshalb gilt cos α = Ankathete : Hypotenuse. Zeile 2: Also ist die Ankathete gleich 20 : cos 40°. Zeile 3: Das sind etwa 26,1 cm. Zeile 4: Die Ankathete wäre länger als die Hypotenuse mit 20 cm. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 1}, "h": "Stelle cos α = Ankathete : Hypotenuse nach der Ankathete um. Muss die Ankathete länger oder kürzer als die Hypotenuse sein?", "w": "Aus cos α = Ankathete : Hypotenuse folgt Ankathete = cos α · Hypotenuse = cos 40° · 20 ≈ 15,3 cm. In Zeile 2 wurde geteilt statt malgenommen. Zeile 4 zeigt den Widerspruch: Eine Kathete ist nie länger als die Hypotenuse.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15608}, {"l": "schnittwinkel", "t": "schnittwinkel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Straße in Norwegen hat 12 % Steigung, das heißt 12 m Höhenunterschied auf 100 m waagerechte Strecke. Unter welchem Winkel steigt sie gegenüber der Waagerechten an? Runde erst das Endergebnis auf eine Dezimalstelle (in Grad)."}, "o": {"wert": 6.8, "einheit": "°"}, "h": "Die Steigung ist das Verhältnis von Höhe zu waagerechter Strecke, also der Tangens des Winkels.", "w": "tan α = 12 : 100 = 0,12. Mit der Umkehrfunktion: α ≈ 6,8°. Bei 12 % Steigung ist der Winkel also viel kleiner als 12°.", "form": "anwenden", "zaehlt": "ja", "r": 15609}, {"l": "schnittwinkel", "t": "schnittwinkel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Geraden y = x und y = 3x schneiden sich im Ursprung. Unter welchem Winkel schneiden sie sich? Runde erst das Endergebnis auf eine Dezimalstelle (in Grad)."}, "o": {"wert": 26.6, "einheit": "°"}, "h": "Jede Gerade bildet mit der x-Achse einen Winkel, dessen Tangens die Steigung ist. Der Schnittwinkel ist der Unterschied.", "w": "Die Gerade y = x hat den Winkel 45° zur x-Achse, die Gerade y = 3x den Winkel arctan 3 ≈ 71,6°. Der Schnittwinkel ist 71,6° − 45° = 26,6°.", "form": "anwenden", "zaehlt": "ja", "r": 15610}]$auf$::jsonb),
    (45, 'zahlen.reell', 619, 14, $auf$[{"l": "zahlarten", "t": "zahlarten", "p": "uebung", "s": 1, "g": "erkennen", "y": "auswahl", "f": {"text": "Welche dieser Zahlen ist irrational?"}, "a": ["√0,81", "√50", "∛64", "√(49/9)"], "o": {"index": 1}, "h": "Eine Quadratwurzel ist rational, wenn der Radikand das Quadrat einer rationalen Zahl ist; eine dritte Wurzel, wenn er die dritte Potenz einer rationalen Zahl ist. Prüfe jede Zahl.", "w": "50 ist keine Quadratzahl (7² = 49 und 8² = 64), und die Wurzel aus einer natürlichen Zahl, die keine Quadratzahl ist, ist nicht als Bruch darstellbar. Also ist √50 irrational. Die anderen sind 0,9, 4 und 7/3, also rational.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15620}, {"l": "zahlarten", "t": "zahlarten", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim sortiert sieben Zahlen: √16, √20, 7/3, π, √(2,25), ∛27 und √45. Wie viele davon sind rational?"}, "o": {"wert": 4}, "h": "Prüfe bei jeder Wurzel, ob der Radikand das Quadrat (oder die dritte Potenz) einer Bruchzahl ist. Brüche sind immer rational.", "w": "√16 = 4, 7/3, √(2,25) = 1,5 und ∛27 = 3 sind rational. 20 und 45 sind keine Quadratzahlen (4² = 16 < 20 < 25 = 5² und 6² = 36 < 45 < 49 = 7²), und die Wurzel aus einer natürlichen Zahl, die keine Quadratzahl ist, ist irrational. Also sind √20 und √45 irrational, ebenso π. Es sind 4 rationale Zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 15621}, {"l": "eingrenzen", "t": "eingrenzen", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du schachtelst √10 ein. Für positive Zahlen gilt ①² = 9 und ②² = 16, also liegt √10 zwischen ① und ②. Für die Zehntel gilt 31² = 961 < 1000 < ③² = 1024.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [3, 4, 32]}, "h": "Suche die Quadratzahlen links und rechts von 10. Bei den Zehnteln rechnest du mit 100-mal so großen Zahlen.", "w": "3² = 9 < 10 < 16 = 4². Also liegt √10 zwischen 3 und 4. Bei Zehnteln gilt 31² = 961 und 32² = 1024, also liegt √10 zwischen 3,1 und 3,2.", "form": "lueckenweg", "zaehlt": "nein", "r": 15622}, {"l": "eingrenzen", "t": "eingrenzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim schachtelt √7 ein: 2,6² = 6,76 und 2,7² = 7,29. Jetzt prüft sie die neun Zahlen 2,61 bis 2,69 mit zwei Nachkommastellen. Wie viele davon sind kleiner als √7?"}, "o": {"wert": 4}, "h": "Quadriere die Zahlen, bis das Quadrat größer als 7 wird. Ab dann sind alle weiteren Zahlen zu groß.", "w": "2,64² = 6,9696 < 7 und 2,65² = 7,0225 > 7. Kleiner als √7 sind also 2,61, 2,62, 2,63 und 2,64: das sind 4 Zahlen. Alle weiteren Zahlen (2,65 bis 2,69) haben ein Quadrat über 7.", "form": "anwenden", "zaehlt": "ja", "r": 15623}, {"l": "heron", "t": "heron", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Beim Heron-Verfahren für √20 startest du mit 4. Der erste Schritt gibt (4 + 20 : 4) : 2 = 4,5. Wie lautet der zweite Wert (4,5 + 20 : 4,5) : 2? Runde auf zwei Dezimalstellen."}, "o": {"wert": 4.47}, "h": "Rechne erst 20 : 4,5, addiere dann 4,5 und teile die Summe durch 2.", "w": "20 : 4,5 ≈ 4,444. Die Summe 4,5 + 4,444 ≈ 8,944. Halbiert: 4,472, gerundet 4,47. Das ist nahe an √20 ≈ 4,4721.", "form": "anwenden", "zaehlt": "ja", "r": 15624}, {"l": "heron", "t": "heron", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "Ein Rechteck hat die Seiten 8 cm und 4,5 cm, die Fläche ist 36 cm². Man ersetzt die Länge durch den Mittelwert beider Seiten, also 6,25 cm, und passt die Breite so an, dass die Fläche 36 cm² bleibt. Wie breit ist das neue Rechteck in Zentimetern?"}, "o": {"wert": 5.76, "einheit": "cm"}, "h": "Die Fläche bleibt gleich: Länge mal Breite = 36. Teile 36 durch die neue Länge.", "w": "Die neue Länge ist (8 + 4,5) : 2 = 6,25 cm. Aus 6,25 · b = 36 folgt b = 36 : 6,25 = 5,76 cm. Die Seiten 6,25 und 5,76 liegen näher an √36 = 6.", "form": "umkehren", "zaehlt": "ja", "r": 15625}, {"l": "wurzel_mal", "t": "wurzel_mal", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Wie groß ist √18 · √50? Fasse die beiden Wurzeln zu einer zusammen."}, "o": {"wert": 30}, "h": "Beim Malnehmen darf man die Zahlen unter den Wurzeln malnehmen: √a · √b = √(a · b).", "w": "√18 · √50 = √(18 · 50) = √900 = 30, denn 30 · 30 = 900.", "form": "anwenden", "zaehlt": "ja", "r": 15626}, {"l": "wurzel_mal", "t": "wurzel_mal", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Welche dieser Gleichungen stimmt?"}, "a": ["√9 + √16 = √25", "√100 − √36 = √64", "√100 : √4 = √25"], "o": {"index": 2}, "h": "Rechne beide Seiten jeder Gleichung einzeln aus und vergleiche.", "w": "√100 : √4 = 10 : 2 = 5 = √25. Beim Teilen und Malnehmen darf man unter einer Wurzel zusammenfassen, bei Plus und Minus nicht.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15627}, {"l": "teilweise", "t": "teilweise", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du vereinfachst √245. Es gilt √245 = √(① · 5) = ② · √5. Damit ist 2 · √245 = ③ · √5.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [49, 7, 14]}, "h": "Suche eine Quadratzahl, die 245 teilt. Ziehe aus ihr die Wurzel und lasse den Rest unter der Wurzel.", "w": "245 = 49 · 5 und √49 = 7, also √245 = 7 · √5. Das Doppelte ist 2 · 7 · √5 = 14 · √5.", "form": "lueckenweg", "zaehlt": "nein", "r": 15628}, {"l": "teilweise", "t": "teilweise", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Beet hat 98 m² Fläche. Seine Seite lässt sich als a · √2 Meter schreiben. Welche ganze Zahl ist a?"}, "o": {"wert": 7}, "h": "Zerlege 98 in ein Produkt, bei dem ein Faktor eine Quadratzahl ist.", "w": "√98 = √(49 · 2) = √49 · √2 = 7 · √2. Also ist a = 7.", "form": "anwenden", "zaehlt": "ja", "r": 15629}, {"l": "zusammenfassen", "t": "zusammenfassen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Noa vereinfacht √8 + √2: Zeile 1: Es gilt √8 = √4 · √2 = 2√2. Zeile 2: Damit ist √8 + √2 = 2√2 + √2. Zeile 3: Gleiche Wurzeln fasst man zusammen, das ergibt 3√2. Zeile 4: Die 3 darf ich unter die Wurzel schreiben, ohne sie zu quadrieren: 3√2 = √6. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Was gilt für eine Zahl vor der Wurzel, wenn sie unter die Wurzel wandert?", "w": "Eine Zahl vor der Wurzel muss unter der Wurzel quadriert werden: 3√2 = √(9 · 2) = √18. Der Fehler steckt in Zeile 4. Die Zeilen 1 bis 3 sind richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15630}, {"l": "nenner_rational", "t": "nenner_rational", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Term 44 : √11 soll ohne Wurzel im Nenner geschrieben werden, und zwar in der Form a · √11. Welche ganze Zahl ist a?"}, "o": {"wert": 4}, "h": "Erweitere den Bruch mit √11, damit der Nenner eine ganze Zahl wird.", "w": "44 / √11 = (44 · √11) / (√11 · √11) = 44√11 / 11 = 4√11. Also ist a = 4.", "form": "anwenden", "zaehlt": "ja", "r": 15631}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Man beweist, dass √2 nicht als gekürzter Bruch p/q geschrieben werden kann. Aus p² = 2q² folgt, dass p gerade ist. Welcher nächste Gedanke führt zum Widerspruch?"}, "a": ["Mit p = 2k folgt q² = 2k², also ist auch q gerade. Dann ließe sich der Bruch p/q durch 2 kürzen.", "Mit p = 2k folgt q = k, also ist p/q = 2.", "Weil p gerade ist, muss q ungerade sein, das ist kein Widerspruch."], "o": {"index": 0}, "h": "Setze p = 2k in die Gleichung p² = 2q² ein. Was folgt für q?", "w": "Aus p = 2k folgt p² = 4k² = 2q², also q² = 2k². Dann ist q² gerade, also ist q gerade. Damit sind p und q beide gerade, der Bruch ist nicht gekürzt. Das widerspricht der Annahme.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15632}, {"l": "irrational_beweis", "t": "irrational_beweis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Sam beweist, dass √2 irrational ist. Er nimmt an, dass √2 = p/q ein gekürzter Bruch mit positiven ganzen Zahlen p und q ist: Zeile 1: Aus √2 = p/q folgt durch Quadrieren 2 = p²/q², also p² = 2q². Zeile 2: Weil p² gerade ist, ist auch p gerade, also p = 2k. Zeile 3: Dann ist p² = 2k², und mit p² = 2q² folgt k² = q². Zeile 4: Also ist k = q, und der Bruch p/q hat die Form 2k/k. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 2}, "h": "Wie lautet p² für p = 2k? Rechne (2k)² nach.", "w": "Es gilt (2k)² = 4k², nicht 2k². Aus 4k² = 2q² folgt q² = 2k², also ist q gerade. Der Fehler steckt in Zeile 3. Zeile 4 rechnet mit dem falschen Ergebnis weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15633}]$auf$::jsonb),
    (46, 'zahlen.wurzeln_basis', 569, 15, $auf$[{"l": "quadratwurzel", "t": "quadratwurzel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein quadratisches Grundstück hat 1296 m² Fläche. Eine Seite ist ① m lang. Der Zaun um das ganze Grundstück ist ② m lang. Aus Zaunstücken zu je 3 m braucht man ③ Stück.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [36, 144, 48]}, "h": "Die Fläche eines Quadrats ist Seite mal Seite. Welche Zahl mit sich selbst malgenommen ergibt 1296?", "w": "36 · 36 = 1296, also ist die Seite √1296 = 36 m lang. Der Umfang ist 4 · 36 = 144 m. Mit 3-m-Stücken braucht man 144 : 3 = 48 Stück.", "form": "lueckenweg", "zaehlt": "nein", "r": 15570}, {"l": "quadratwurzel", "t": "quadratwurzel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratischer Sportplatz hat 5929 m² Fläche. Kim läuft eine Runde am Rand entlang. Wie viele Meter ist eine Runde lang?"}, "o": {"wert": 308, "einheit": "m"}, "h": "Zuerst brauchst du die Seitenlänge. Welche Zahl mit sich selbst malgenommen ergibt 5929?", "w": "77 · 77 = 5929, also ist eine Seite 77 m lang. Eine Runde ist der Umfang: 4 · 77 = 308 m.", "form": "anwenden", "zaehlt": "ja", "r": 15571}, {"l": "quadratwurzel", "t": "quadratwurzel", "p": "uebung", "s": 2, "g": "umkehr", "y": "auswahl", "f": {"text": "Welche Zahl hat die Quadratwurzel 24?"}, "a": ["576", "48", "12"], "o": {"index": 0}, "h": "Quadratwurzel und Quadrat gehören zusammen: Rechne von 24 zurück.", "w": "Gesucht ist die Zahl, deren Wurzel 24 ist, also das Quadrat von 24: 24 · 24 = 576. Probe: √576 = 24.", "form": "umkehren", "zaehlt": "ja", "r": 15572}, {"l": "wurzel_dezimal", "t": "wurzel_dezimal", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine quadratische Fliese hat die Fläche 0,0169 m². Wie lang ist eine Seite in Zentimetern?"}, "o": {"wert": 13, "einheit": "cm"}, "h": "Die Wurzel aus 0,0169 ist kleiner als 1. Rechne zuerst in Metern und wechsle dann in Zentimeter.", "w": "0,13 · 0,13 = 0,0169, also ist die Seite √0,0169 = 0,13 m lang. Das sind 0,13 · 100 = 13 cm.", "form": "anwenden", "zaehlt": "ja", "r": 15573}, {"l": "wurzel_dezimal", "t": "wurzel_dezimal", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Solarpanel hat eine Fläche von 3,8 m². Wie lang ist eine Seite? Runde auf zwei Dezimalstellen."}, "o": {"wert": 1.95, "einheit": "m"}, "h": "Suche die Zahl, die mit sich selbst malgenommen 3,8 ergibt. Probiere mit einer Zahl zwischen 1 und 2.", "w": "Die Seite ist √3,8 ≈ 1,95 m lang. Probe: 1,95 · 1,95 = 3,8025, das ist fast 3,8.", "form": "anwenden", "zaehlt": "ja", "r": 15574}, {"l": "kubikwurzel", "t": "kubikwurzel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein würfelförmiges Aquarium fasst 343 Liter, das sind 343 dm³. Seine Kante ist ① dm lang, die Bodenfläche ② dm². Die Oberfläche aller sechs Seitenflächen ist ③ dm².", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 49, 294]}, "h": "Beim Würfel ist das Volumen Kante mal Kante mal Kante. Welche Zahl dreimal mit sich malgenommen ergibt 343?", "w": "7 · 7 · 7 = 343, also ist die Kante ∛343 = 7 dm lang. Die Bodenfläche ist 7 · 7 = 49 dm². Die sechs Seitenflächen: 6 · 49 = 294 dm².", "form": "lueckenweg", "zaehlt": "nein", "r": 15575}, {"l": "kubikwurzel", "t": "kubikwurzel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein würfelförmiger Container hat das Volumen 2744 dm³. Wie groß ist seine gesamte Oberfläche in Quadratdezimetern?"}, "o": {"wert": 1176, "einheit": "dm²"}, "h": "Berechne zuerst die Kantenlänge. Wie viele Seitenflächen hat ein Würfel?", "w": "14 · 14 · 14 = 2744, also ist die Kante 14 dm lang. Eine Seitenfläche hat 14 · 14 = 196 dm². Die Oberfläche ist 6 · 196 = 1176 dm².", "form": "anwenden", "zaehlt": "ja", "r": 15576}, {"l": "kubikwurzel", "t": "kubikwurzel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex bestimmt die Kante eines Würfels mit dem Volumen 216 cm³: Zeile 1: Die Kante ist die dritte Wurzel aus 216, also 216 geteilt durch 3. Zeile 2: Das sind 72 cm. Zeile 3: Die Grundfläche wäre dann 72 · 72 = 5184 cm². In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Die dritte Wurzel fragt: Welche Zahl dreimal mit sich selbst malgenommen ergibt 216? Ist 216 geteilt durch 3 so eine Zahl?", "w": "Die dritte Wurzel ist keine Division durch 3. Gesucht ist die Zahl, die dreimal mit sich malgenommen 216 ergibt: 6 · 6 · 6 = 216, die Kante ist 6 cm. Zeile 1 ist der erste Fehler, die Zeilen 2 und 3 rechnen mit dem falschen Wert richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15577}, {"l": "abschaetzen", "t": "abschaetzen", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Ein quadratischer Teppich hat 130 dm² Fläche. Die Länge seiner Seite liegt in dm zwischen welchen zwei ganzen Zahlen?"}, "a": ["zwischen 12 dm und 13 dm", "zwischen 10 dm und 11 dm", "zwischen 65 dm und 66 dm", "zwischen 11 dm und 12 dm"], "o": {"index": 3}, "h": "Suche die Quadratzahlen links und rechts von 130.", "w": "11² = 121 und 12² = 144. Weil 121 < 130 < 144 gilt, liegt √130 zwischen 11 und 12.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15578}, {"l": "abschaetzen", "t": "abschaetzen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Kim will wissen, wie lang die Seite eines quadratischen Zeltbodens mit 85 m² Fläche ungefähr ist. Wie lang ist sie? Runde auf eine Dezimalstelle."}, "o": {"wert": 9.2, "einheit": "m"}, "h": "Die Seite liegt zwischen zwei ganzen Zahlen. Probiere dann Zehntel: Welches Zehntel passt am besten?", "w": "9² = 81 und 10² = 100, also liegt √85 zwischen 9 und 10. Es gilt 9,2 · 9,2 = 84,64 und 9,3 · 9,3 = 86,49. Näher an 85 liegt 9,2. Die Seite ist etwa 9,2 m lang.", "form": "anwenden", "zaehlt": "ja", "r": 15579}, {"l": "wurzel_deuten", "t": "wurzel_deuten", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Warum hat √(−25) im Bereich der reellen Zahlen keinen Wert?"}, "a": ["Weil 25 keine Quadratzahl ist.", "Weil man nur aus geraden Zahlen die Wurzel ziehen kann.", "Keine reelle Zahl mit sich selbst malgenommen ergibt eine negative Zahl."], "o": {"index": 2}, "h": "Prüfe: Was kommt heraus, wenn du eine positive oder eine negative Zahl mit sich selbst malnimmst?", "w": "Ein Quadrat ist nie negativ: positiv mal positiv ist positiv, negativ mal negativ ist ebenfalls positiv. Also gibt es keine reelle Zahl, deren Quadrat −25 ist.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15580}, {"l": "wurzel_deuten", "t": "wurzel_deuten", "p": "uebung", "s": 3, "g": "parameter", "y": "zahl", "f": {"text": "Für wie viele ganze Zahlen x von −3 bis 12 (beide Grenzen eingeschlossen) ist der Ausdruck √(x − 5) im Bereich der reellen Zahlen definiert?"}, "o": {"wert": 8}, "h": "Der Wert unter der Wurzel darf nicht negativ sein. Ab welchem x ist x − 5 mindestens 0?", "w": "Es muss x − 5 ≥ 0 gelten, also x ≥ 5. Die Zahlen 5, 6, 7, 8, 9, 10, 11 und 12 erfüllen das. Das sind 8 Zahlen.", "form": "anwenden", "zaehlt": "ja", "r": 15581}, {"l": "wurzel_deuten", "t": "wurzel_deuten", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Sam berechnet die Wurzel aus der Summe 4 + 25: Zeile 1: Die Wurzel kann man auf die Summanden verteilen: √(4 + 25) = √4 + √25. Zeile 2: Mit √4 = 2 und √25 = 5 folgt für √29 der Wert 7. Zeile 3: Dann müsste 29 gleich 7 mal 7 sein. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 0}, "h": "Berechne 7 · 7. Passt das Ergebnis zu 29?", "w": "Bei Plus darf man die Wurzel nicht auf die Summanden verteilen. √29 ist etwa 5,4, nicht 7. Zeile 3 zeigt den Widerspruch: 7 · 7 = 49 und nicht 29. Der Fehler steckt in Zeile 1.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15582}, {"l": "wurzel_sache", "t": "wurzel_sache", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein quadratisches Stadtviertel in Lissabon hat eine Fläche von 2,25 km². Kim geht einmal am Rand des Viertels herum, mit 5 km/h. Wie viele Minuten braucht sie?"}, "o": {"wert": 72, "einheit": "min"}, "h": "Rechne zuerst die Seitenlänge aus. Dann den Weg um das Viertel, dann die Zeit.", "w": "1,5 · 1,5 = 2,25, also ist die Seite 1,5 km lang. Der Weg ist 4 · 1,5 = 6 km. Bei 5 km/h dauert das 6 : 5 = 1,2 Stunden, das sind 1,2 · 60 = 72 Minuten.", "form": "anwenden", "zaehlt": "ja", "r": 15583}, {"l": "wurzel_sache", "t": "wurzel_sache", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Eine würfelförmige Kiste hat das Volumen 3,375 m³. Kim klebt ein Band an allen zwölf Kanten entlang. Wie viele Meter Band braucht sie?"}, "o": {"wert": 18, "einheit": "m"}, "h": "Wie lang ist eine Kante, wenn dreimal Kante malgenommen 3,375 ergibt?", "w": "1,5 · 1,5 · 1,5 = 3,375, also ist eine Kante 1,5 m lang. Ein Würfel hat 12 Kanten: 12 · 1,5 = 18 m.", "form": "anwenden", "zaehlt": "ja", "r": 15584}]$auf$::jsonb),
    (54, 'abbildungen.kongruenz', 686, 14, $auf$[{"l": "achsenspiegelung", "t": "achsenspiegelung", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Der Punkt P(2 | 5) wird an der senkrechten Geraden x = 6 gespiegelt. P hat von dieser Geraden den Abstand ①. Der Bildpunkt P' liegt auf der anderen Seite im selben Abstand. Seine x-Koordinate ist ②. Die Strecke PP' ist ③ Einheiten lang.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [4, 10, 8]}, "h": "Spiegeln heißt: gleich weit auf die andere Seite der Achse. Die y-Koordinate bleibt bei einer senkrechten Achse gleich.", "w": "Abstand von P zur Achse: 6 − 2 = 4. P' liegt 4 Einheiten rechts der Achse: x = 6 + 4 = 10, also P'(10 | 5). Die Strecke PP' ist 10 − 2 = 8 Einheiten lang, doppelt so lang wie der Abstand zur Achse.", "form": "lueckenweg", "zaehlt": "nein", "r": 15687}, {"l": "achsenspiegelung", "t": "achsenspiegelung", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Auf einem Stadtplan verläuft ein gerader Kanal senkrecht entlang der Geraden x = 1. Ein Café liegt im Punkt A(5 | −2). Ein Zwillingscafé B soll genau gegenüber auf der anderen Kanalseite liegen, als Spiegelbild von A am Kanal. Welche x-Koordinate hat B?"}, "o": {"wert": -3}, "h": "Wie weit ist A vom Kanal entfernt? B liegt im gleichen Abstand auf der anderen Seite.", "w": "A hat vom Kanal den Abstand 5 − 1 = 4. B liegt 4 Einheiten links vom Kanal: x = 1 − 4 = −3. Die y-Koordinate bleibt −2. B(−3 | −2).", "form": "anwenden", "zaehlt": "ja", "r": 15688}, {"l": "achsenspiegelung", "t": "achsenspiegelung", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Das Dreieck mit A(2 | 1), B(5 | 1) und C(2 | 4) wird an der y-Achse gespiegelt. Kim schreibt auf: Zeile 1: Bei einer Spiegelung an der y-Achse wechselt die x-Koordinate das Vorzeichen, die y-Koordinate bleibt. Zeile 2: Also wird A zu A'(−2 | 1), B zu B'(−5 | 1) und C zu C'(−2 | −4). Zeile 3: Die Strecke [A'C'] ist dann 5 Einheiten lang, die Strecke [AC] war nur 3 Einheiten lang. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Vergleiche die Koordinaten der Bildpunkte mit der Regel aus Zeile 1. Bleibt bei einer Spiegelung die Länge einer Strecke gleich?", "w": "Nach der Regel in Zeile 1 bleibt die y-Koordinate gleich, daher ist C'(−2 | 4) richtig und nicht C'(−2 | −4). Der Fehler steckt in Zeile 2. Zeile 3 rechnet mit dem falschen C' richtig weiter. Der Widerspruch (5 und 3 Einheiten) zeigt, dass etwas nicht stimmt, denn eine Spiegelung erhält Längen.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15689}, {"l": "mittelsenkrechte", "t": "mittelsenkrechte", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei Bergstationen liegen im Koordinatensystem bei A(−6 | 2) und B(12 | 2). Ein Wanderweg soll überall gleich weit von A und B entfernt sein und verläuft senkrecht (parallel zur y-Achse). Er liegt auf der Geraden x = k. Wie groß ist k?"}, "o": {"wert": 3}, "h": "Der Weg liegt auf der Mittelsenkrechten von AB. Sie geht durch die Mitte der Strecke.", "w": "Die Mittelsenkrechte von AB geht durch den Mittelpunkt von [AB]. Die x-Koordinate der Mitte ist (−6 + 12) : 2 = 3. Der Weg liegt auf der Geraden x = 3.", "form": "anwenden", "zaehlt": "ja", "r": 15690}, {"l": "mittelsenkrechte", "t": "mittelsenkrechte", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Im Dreieck ABC liegt der Punkt C auf der Mittelsenkrechten der Seite [AB]. Es gilt AB = 12 cm. Der Umfang des Dreiecks beträgt 30 cm. Wie lang ist die Seite [AC]?"}, "o": {"wert": 9, "einheit": "cm"}, "h": "Jeder Punkt auf der Mittelsenkrechten ist von A und B gleich weit entfernt. Was folgt für AC und BC?", "w": "C liegt auf der Mittelsenkrechten, also gilt AC = BC. Der Umfang ist AB + AC + BC = 30. Mit AB = 12 bleiben für AC und BC zusammen 18 cm, also AC = 9 cm.", "form": "umkehren", "zaehlt": "ja", "r": 15691}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Im Dreieck ABC gilt α = 68° und β = 52°. Die Winkelhalbierende von γ teilt den Winkel γ in zwei gleich große Teile. Wie groß ist der Winkel zwischen dieser Winkelhalbierenden und der Seite [AC]?"}, "o": {"wert": 30, "einheit": "°"}, "h": "Berechne zuerst γ mit der Winkelsumme im Dreieck. Halbiere dann.", "w": "γ = 180° − 68° − 52° = 60°. Die Winkelhalbierende teilt γ in zwei Teile zu je 30°. Der gesuchte Winkel ist 30°.", "form": "anwenden", "zaehlt": "ja", "r": 15692}, {"l": "winkelhalbierende", "t": "winkelhalbierende", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "Ein Café soll von zwei sich kreuzenden Straßen gleich weit entfernt sein und außerdem von den Bushaltestellen H1 und H2 gleich weit entfernt. Wie findest du alle möglichen Orte?"}, "a": ["Schneide die Mittelsenkrechte von [H1H2] mit jeder der beiden Winkelhalbierenden der Straßen und sammle alle Treffer", "Schnitt aus der Mittelsenkrechten der beiden Straßen und der Winkelhalbierenden von [H1H2]", "Schnitt zweier Winkelhalbierender", "Schnitt zweier Mittelsenkrechter"], "o": {"index": 0}, "h": "Gleich weit von zwei Geraden entfernt und gleich weit von zwei Punkten entfernt sind zwei verschiedene Bedingungen. Welche Linie gehört zu welcher?", "w": "Gleicher Abstand zu zwei sich kreuzenden Geraden: eine der beiden Winkelhalbierenden der Geraden (es gibt zwei, senkrecht zueinander). Gleicher Abstand zu zwei Punkten: Mittelsenkrechte der Strecke zwischen den Punkten. Der gesuchte Ort liegt auf der Mittelsenkrechten und auf einer der beiden Winkelhalbierenden, also in den Treffern beider Schnitte. Sonderfälle: Ist die Mittelsenkrechte parallel zu einer Winkelhalbierenden, gibt es dort keinen Treffer; fällt sie mit einer zusammen (zum Beispiel Straßen x- und y-Achse, Haltestellen (1|0) und (0|1)), erfüllen alle Punkte dieser Geraden die Bedingung.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15693}, {"l": "symmetrie", "t": "symmetrie", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein regelmäßiges Sechseck hat ① Symmetrieachsen. Ein regelmäßiges Zwölfeck hat ② Symmetrieachsen. ③ ist die Summe der beiden Achsenzahlen der einzelnen Figuren (nicht die Achsen einer zusammengesetzten Figur).", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [6, 12, 18]}, "h": "Ein regelmäßiges n-Eck hat n Symmetrieachsen. Bei geradem n gehen sie durch gegenüberliegende Ecken oder durch gegenüberliegende Seitenmitten. Addiere für die letzte Lücke die Anzahlen der beiden einzelnen Figuren.", "w": "Ein regelmäßiges n-Eck hat n Symmetrieachsen. Sechseck: 6, Zwölfeck: 12, zusammen 6 + 12 = 18.", "form": "lueckenweg", "zaehlt": "nein", "r": 15694}, {"l": "symmetrie", "t": "symmetrie", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Auf Reisen siehst du drei Verkehrsschilder: ein Vorfahrt-gewähren-Schild (gleichseitiges Dreieck), ein Stoppschild (regelmäßiges Achteck) und ein Vorfahrtstraßen-Schild (Quadrat, auf der Spitze stehend). Wie viele Symmetrieachsen haben die drei Schilder zusammen? Bunte Zeichen und Schrift bleiben unbeachtet, nur die Umrissform zählt."}, "o": {"wert": 15, "einheit": "Achsen"}, "h": "Zähle für jede Umrissform die Achsen. Ein regelmäßiges Vieleck mit n Ecken hat n Achsen.", "w": "Gleichseitiges Dreieck: 3 Achsen. Regelmäßiges Achteck: 8 Achsen. Quadrat: 4 Achsen (zwei Mittellinien und zwei Diagonalen). Zusammen 3 + 8 + 4 = 15 Achsen.", "form": "anwenden", "zaehlt": "ja", "r": 15695}, {"l": "symmetrie", "t": "symmetrie", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex untersucht ein Rechteck, das kein Quadrat ist, und schreibt auf: Zeile 1: Ein Rechteck hat zwei Paare gleich langer Seiten. Zeile 2: Die beiden Diagonalen sind gleich lang, also sind sie auch Symmetrieachsen. Zeile 3: Zusammen mit den zwei Mittellinien hat das Rechteck 4 Symmetrieachsen. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Falte ein Rechteck gedanklich entlang einer Diagonalen. Passen die beiden Hälften genau aufeinander?", "w": "Faltet man ein Rechteck (das kein Quadrat ist) an einer Diagonalen, passen die Hälften nicht aufeinander. Nur die beiden Mittellinien sind Symmetrieachsen, also hat es 2 Achsen. Der Fehler steckt in Zeile 2. Zeile 3 rechnet mit der falschen Aussage weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15696}, {"l": "vierecke_ordnen", "t": "vierecke_ordnen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Ein Viereck hat vier gleich lange Seiten. Seine Diagonalen stehen senkrecht aufeinander und halbieren sich. Die Diagonalen sind aber verschieden lang. Welches Viereck ist es?"}, "a": ["ein Rechteck", "ein Drachen, der keine Raute ist", "eine Raute, die kein Quadrat ist", "ein Quadrat"], "o": {"index": 2}, "h": "Gehe im Haus der Vierecke nach den Eigenschaften vor: Vier gleich lange Seiten, senkrechte Diagonalen, verschieden lange Diagonalen.", "w": "Vier gleich lange Seiten und sich halbierende, senkrechte Diagonalen passen zur Raute. Gleich lange Diagonalen hätte nur das Quadrat. Da sie verschieden lang sind, ist es eine Raute, die kein Quadrat ist.", "form": "bruecke", "zaehlt": "ja", "r": 15697}, {"l": "vierecke_ordnen", "t": "vierecke_ordnen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Bei einem Puzzle-Spiel liegen sechs Vierecke bereit: Quadrat, Rechteck, Raute, Parallelogramm (ein allgemeines Parallelogramm, das weder Rechteck noch Raute ist), Drachen und gleichschenkliges Trapez. Kim soll alle heraussuchen, die mindestens eine Symmetrieachse haben. Wie viele sind das?"}, "o": {"wert": 5, "einheit": "Vierecke"}, "h": "Prüfe jedes Viereck einzeln: Gibt es eine Gerade, an der man die Figur falten kann, sodass beide Hälften genau aufeinanderliegen?", "w": "Quadrat, Rechteck, Raute, Drachen und gleichschenkliges Trapez haben mindestens eine Symmetrieachse. Das Parallelogramm (ohne rechten Winkel und ohne gleich lange Nachbarseiten) hat keine, nur eine Punktsymmetrie. Es sind 5 Vierecke.", "form": "anwenden", "zaehlt": "ja", "r": 15698}, {"l": "eigenschaften", "t": "eigenschaften", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim zeichnet ein Dreieck ABC mit α = 52° und β = 71°. Sie spiegelt es an einer Geraden und verschiebt das Bild danach um einige Einheiten. Wie groß ist der Winkel γ' im Bilddreieck A'B'C'?"}, "o": {"wert": 57, "einheit": "°"}, "h": "Welche Größen ändern sich bei Spiegeln und Verschieben, und welche bleiben gleich? Berechne γ aus der Winkelsumme.", "w": "Spiegeln und Verschieben erhalten alle Winkel. Also ist γ' = γ = 180° − 52° − 71° = 57°.", "form": "anwenden", "zaehlt": "ja", "r": 15699}, {"l": "eigenschaften", "t": "eigenschaften", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Dreieck ABC ist gegen den Uhrzeigersinn beschriftet. Es wird einmal gespiegelt, dann noch einmal an einer anderen Achse gespiegelt und schließlich verschoben. Kim schreibt auf: Zeile 1: Eine Verschiebung ändert den Umlaufsinn nicht. Zeile 2: Die erste Spiegelung kehrt den Umlaufsinn um: A'B'C' ist im Uhrzeigersinn beschriftet. Zeile 3: Die zweite Spiegelung kehrt ihn noch einmal um: A''B''C'' ist wieder gegen den Uhrzeigersinn beschriftet. Zeile 4: Also ist das Endbild nach dem Verschieben im Uhrzeigersinn beschriftet. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Zähle, wie oft der Umlaufsinn insgesamt umgekehrt wird. Gerade oder ungerade Zahl?", "w": "Zwei Spiegelungen kehren den Umlaufsinn zweimal um, das Verschieben ändert nichts. Das Endbild ist wieder gegen den Uhrzeigersinn beschriftet. Die Zeilen 1 bis 3 sind richtig. Der Fehler steckt in Zeile 4: Sie passt nicht zu Zeile 3.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15700}]$auf$::jsonb),
    (55, 'bruch.prozent_grundwert', 529, 16, $auf$[{"l": "faktor", "t": "faktor", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Hostel in Lissabon verlangt in der Hauptsaison 18 % mehr als in der Nebensaison. Ein Gast will den Hauptsaison-Preis aus dem Nebensaison-Preis ausrechnen: Preis · Faktor. Welchen Faktor setzt er ein?"}, "o": {"wert": 1.18}, "h": "Der alte Preis bleibt voll erhalten (100 %). Dazu kommen die 18 %.", "w": "Der alte Preis ist 100 %. Dazu kommen 18 %: 100 % + 18 % = 118 %. Als Faktor schreibt man 118 : 100 = 1,18.", "form": "anwenden", "zaehlt": "ja", "r": 15530}, {"l": "faktor", "t": "faktor", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein Reiseveranstalter senkt den Preis einer Tour um 12 %. Kim bestimmt den Faktor und rechnet damit einen Preis aus. Zeile 1: Bei 12 % weniger bleiben 100 % − 12 % = 88 % übrig. Zeile 2: 88 % sind der Faktor 0,088. Zeile 3: Eine Tour, die vorher 450 € kostete, kostet jetzt 450 · 0,088 = 39,60 €. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Wie viele Hundertstel sind 88 %? Schreibe 88 : 100 als Dezimalzahl.", "w": "88 % sind 88 : 100 = 0,88, nicht 0,088. Der Fehler steckt in Zeile 2. Zeile 3 rechnet mit dem falschen Faktor richtig weiter. Richtig ist 450 · 0,88 = 396 €.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15531}, {"l": "vermehrt", "t": "vermehrt", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Der Grundpreis für einen Mietwagen auf Sizilien beträgt 320 € für die Woche. Für einen Zusatzfahrer kommen 15 % des Grundpreises dazu, für die Vollkasko-Versicherung noch einmal 8 % des Grundpreises. Wie viel Euro kostet der Wagen insgesamt?"}, "o": {"wert": 393.6, "einheit": "€"}, "h": "Beide Zuschläge sind Prozente vom Grundpreis (320 €), nicht vom schon erhöhten Preis.", "w": "Beide Zuschläge beziehen sich auf 320 €: 15 % von 320 € sind 48 €, 8 % von 320 € sind 25,60 €. Zusammen: 320 + 48 + 25,60 = 393,60 €. Mit Faktor: 320 · 1,23 = 393,60 €.", "form": "anwenden", "zaehlt": "ja", "r": 15532}, {"l": "vermehrt", "t": "vermehrt", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Auf einem Markt in Istanbul nennt ein Händler für einen Teppich 480 Lira. Für Touristen schlägt er 25 % auf. Kim rechnet mit dem Kurs 1 € = 40 Lira. Wie viel Euro muss Kim mit dem Touristen-Aufschlag zahlen?"}, "o": {"wert": 15, "einheit": "€"}, "h": "Rechne zuerst in Lira, dann in Euro um.", "w": "Der Preis mit Aufschlag ist 480 · 1,25 = 600 Lira. Bei 40 Lira je Euro sind das 600 : 40 = 15 €.", "form": "anwenden", "zaehlt": "ja", "r": 15533}, {"l": "vermindert", "t": "vermindert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Skiverleih berechnet 28 € je Tag. Ab dem vierten Tag gibt es 30 % Nachlass auf den Tagespreis. Familie Berger leiht die Ausrüstung für 6 Tage. Wie viel Euro zahlt sie insgesamt?"}, "o": {"wert": 142.8, "einheit": "€"}, "h": "Drei Tage kosten den vollen Preis. Für die anderen Tage gilt der Rest-Anteil von 70 %.", "w": "Tage 1 bis 3: 3 · 28 € = 84 €. Ab Tag 4 zahlt man 70 % von 28 €, das sind 19,60 € je Tag. Für 3 Tage: 58,80 €. Zusammen: 84 + 58,80 = 142,80 €.", "form": "anwenden", "zaehlt": "ja", "r": 15534}, {"l": "vermindert", "t": "vermindert", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Rucksack kostet 85 € und wird um 35 % reduziert. Berechne den neuen Preis auf zwei Wegen. Weg A: Rabatt in Euro ausrechnen und abziehen. Weg B: den Preis mit dem Rest-Anteil malnehmen. Wie viel Euro kostet der Rucksack jetzt?"}, "o": {"wert": 55.25, "einheit": "€"}, "h": "Weg B: Wie viel Prozent vom alten Preis bleiben nach 35 % Rabatt übrig?", "w": "Weg A: 35 % von 85 € sind 29,75 €. 85 − 29,75 = 55,25 €. Weg B: 100 % − 35 % = 65 %, also 85 · 0,65 = 55,25 €. Beide Wege ergeben 55,25 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 15535}, {"l": "zurueck", "t": "zurueck", "p": "uebung", "s": 2, "g": "umkehr", "y": "zahl", "f": {"text": "In einem Hotel in Split kostet ein Zimmer inklusive 8 % Ortstaxen-Zuschlag 162 € je Nacht. Wie viel Euro kostet das Zimmer ohne den Zuschlag?"}, "o": {"wert": 150, "einheit": "€"}, "h": "Der Preis mit Zuschlag ist 108 % vom Preis ohne Zuschlag. Wie kommst du von 108 % zurück auf 100 %?", "w": "Der Preis mit Zuschlag ist 108 % des ursprünglichen Preises, also Preis · 1,08 = 162 €. Zurück geht es durch Teilen: 162 : 1,08 = 150 €.", "form": "umkehren", "zaehlt": "ja", "r": 15536}, {"l": "zurueck", "t": "zurueck", "p": "uebung", "s": 3, "g": "transfer", "y": "auswahl", "f": {"text": "Ticket A kostet nach einem Aufschlag von 20 % jetzt 60 €. Ticket B kostet nach einem Rabatt von 20 % jetzt 60 €. Welche Aussage stimmt?"}, "a": ["Ticket A war vorher teurer: 75 € gegenüber 50 €.", "Beide Tickets kosteten vorher gleich viel, denn 20 % mehr und 20 % weniger gleichen sich aus.", "Ticket B war vorher teurer: 75 € gegenüber 50 €.", "Ticket B war vorher teurer: 72 € gegenüber 48 €."], "o": {"index": 2}, "h": "Zum Zurückrechnen brauchst du jeweils den Faktor: nach Aufschlag und nach Rabatt ist er verschieden.", "w": "Ticket A: Preis · 1,2 = 60 €, also Preis = 60 : 1,2 = 50 €. Ticket B: Preis · 0,8 = 60 €, also Preis = 60 : 0,8 = 75 €. B war vorher teurer.", "form": "anwenden", "zaehlt": "ja", "r": 15537}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Im Mai bekam man für 100 € auf einer Reise 4 300 Baht. Im Juli waren es nur noch 4 085 Baht. Um wie viel Prozent ist der Baht-Betrag für 100 € gesunken?"}, "o": {"wert": 5, "einheit": "%"}, "h": "Vergleiche die Änderung mit dem Wert vom Mai, nicht mit dem vom Juli.", "w": "Die Änderung ist 4 300 − 4 085 = 215 Baht. Bezogen auf den alten Wert: 215 : 4 300 = 0,05 = 5 %. Der Betrag ist um 5 % gesunken.", "form": "anwenden", "zaehlt": "ja", "r": 15538}, {"l": "prozentsatz", "t": "prozentsatz", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "auswahl", "f": {"text": "In der Tabelle stehen alter und neuer Preis von drei Angeboten auf einer Reise. Bei welchem Angebot ist die Preiserhöhung in Prozent am größten?", "grafik": {"typ": "tabelle", "kopf": ["Angebot", "alter Preis", "neuer Preis"], "zeilen": [["Bus", "2,40 €", "3,00 €"], ["Museum", "15 €", "18 €"], ["Hotel", "90 €", "99 €"]]}}, "a": ["beim Hotel, weil dort die Erhöhung in Euro am größten ist", "beim Bus", "beim Museum, weil es mit 3 € mehr steigt als der Bus (0,60 €) und im Verhältnis zum Preis mehr als das Hotel"], "o": {"index": 1}, "h": "Berechne für jede Zeile: Änderung geteilt durch den alten Preis.", "w": "Bus: 0,60 : 2,40 = 25 %. Museum: 3 : 15 = 20 %. Hotel: 9 : 90 = 10 %. Die größte Erhöhung in Prozent hat der Bus, auch wenn sie in Euro am kleinsten ist.", "form": "bruecke", "zaehlt": "ja", "r": 15539}, {"l": "mehrfach", "t": "mehrfach", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Fähre nach Sardinien kostet für das Auto 480 €. Wegen der Hochsaison steigt der Preis zuerst um 12 %. Auf diesen neuen Preis kommen für die Stornoversicherung noch einmal 5 %. Wie viel Euro kostet die Überfahrt insgesamt?"}, "o": {"wert": 564.48, "einheit": "€"}, "h": "Die zweite Erhöhung bezieht sich auf den schon erhöhten Preis. Nimm beide Faktoren mal.", "w": "Nach der ersten Erhöhung: 480 · 1,12 = 537,60 €. Darauf 5 %: 537,60 · 1,05 = 564,48 €. Man darf die Prozente nicht addieren (17 % wären nur 561,60 €).", "form": "anwenden", "zaehlt": "ja", "r": 15540}, {"l": "mehrfach", "t": "mehrfach", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Preis steigt zuerst um 20 %. Danach soll er um einen Prozentsatz sinken, sodass er wieder genau so hoch ist wie am Anfang. Um wie viel Prozent muss er sinken? Runde auf eine Dezimalstelle."}, "o": {"wert": 16.7, "einheit": "%"}, "h": "Nach der Erhöhung ist der Preis das 1,2-Fache. Mit welchem Faktor kommst du von 1,2 zurück auf 1?", "w": "Nach der Erhöhung gilt: Preis · 1,2. Gesucht ist der Faktor q mit 1,2 · q = 1, also q = 1 : 1,2 ≈ 0,8333. Das ist eine Abnahme um 1 − 0,8333 = 0,1667, also etwa 16,7 %.", "form": "umkehren", "zaehlt": "ja", "r": 15541}, {"l": "formel", "t": "formel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Kim legt 5 000 € für 3 Jahre zu 4 % Zinsen im Jahr an. Die Zinsen bleiben auf dem Konto und werden mitverzinst. Berechne das Guthaben nach 3 Jahren auf zwei Wegen. Weg A: Jahr für Jahr mit 1,04 malnehmen. Weg B: mit 1,04³. Runde auf Cent. Wie viel Euro sind es?"}, "o": {"wert": 5624.32, "einheit": "€"}, "h": "Weg A und Weg B müssen dasselbe ergeben. Wie oft kommt der Faktor 1,04 vor?", "w": "Weg A: 5 000 · 1,04 = 5 200; 5 200 · 1,04 = 5 408; 5 408 · 1,04 = 5 624,32. Weg B: 5 000 · 1,04³ = 5 000 · 1,124864 = 5 624,32 €.", "form": "zwei_wege", "zaehlt": "ja", "r": 15542}, {"l": "formel", "t": "formel", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Guthaben von 2 000 € wird mit 5 % Zinseszins im Jahr angelegt. Nach wie vielen vollen Jahren ist das Guthaben zum ersten Mal höher als 2 500 €?"}, "o": {"wert": 5, "einheit": "Jahre"}, "h": "Multipliziere den Kontostand jedes Jahr wieder mit 1,05 (Stand nach 1 Jahr: 2 000 · 1,05, danach diesen Stand wieder mal 1,05, und so weiter) oder rechne für jedes Jahr n getrennt 2 000 · 1,05ⁿ. Wann liegt das Ergebnis erstmals über 2 500?", "w": "Nach 4 Jahren: 2 000 · 1,05⁴ ≈ 2 431,01 €, das reicht noch nicht. Nach 5 Jahren: 2 000 · 1,05⁵ ≈ 2 552,56 €. Das ist höher als 2 500 €. Es sind 5 Jahre.", "form": "umkehren", "zaehlt": "ja", "r": 15543}, {"l": "argumente", "t": "argumente", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Eine Stadt am Mittelmeer hatte im Vorjahr 200 000 Übernachtungen und dieses Jahr 230 000. Eine kleine Insel hatte im Vorjahr 50 000 und dieses Jahr 62 000. Welche Aussage vergleicht das relative Wachstum (den prozentualen Zuwachs) von Stadt und Insel richtig?"}, "a": ["Die Insel ist prozentual stärker gewachsen: 12 000 : 50 000 = 24 %, in der Stadt sind es 30 000 : 200 000 = 15 %.", "Die Stadt ist stärker gewachsen, denn 30 000 ist mehr als 12 000.", "Beide sind gleich stark gewachsen, denn jeweils kamen etwa ein Fünftel mehr Übernachtungen dazu."], "o": {"index": 0}, "h": "Ein Vergleich in Prozent braucht jeweils den Zuwachs geteilt durch den Wert des Vorjahrs.", "w": "Stadt: 230 000 − 200 000 = 30 000, das sind 30 000 : 200 000 = 15 %. Insel: 62 000 − 50 000 = 12 000, das sind 12 000 : 50 000 = 24 %. Die Insel ist prozentual stärker gewachsen.", "form": "anwenden", "zaehlt": "ja", "r": 15544}, {"l": "argumente", "t": "argumente", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Ein Ticket kostet 50 €. Der Preis steigt um 40 % und sinkt später um 40 %. Ein Reiseblogger schreibt: „Dann ist es wieder so billig wie am Anfang.“ Welche Rechnung prüft die Aussage richtig?"}, "a": ["50 · 1,4 · 0,6 = 42, also kostet das Ticket am Ende weniger als am Anfang.", "50 + 40 − 40 = 50, also stimmt die Aussage.", "50 · 1,4 · 1,4 = 98, also kostet das Ticket am Ende mehr.", "50 · 0,4 · 0,4 = 8, also kostet das Ticket nur noch 8 €."], "o": {"index": 0}, "h": "Prüfe die Aussage mit einer Rechnung: Die zweite Änderung gilt für den neuen, nicht für den alten Preis.", "w": "Nach +40 % kostet es 50 · 1,4 = 70 €. Nach −40 % davon: 70 · 0,6 = 42 €. Das ist weniger als 50 €. Die Aussage ist falsch, weil sich die 40 % auf verschiedene Grundwerte beziehen.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15545}]$auf$::jsonb),
    (57, 'geometrie.konstruktion', 618, 15, $auf$[{"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Ein gleichschenkliges Dreieck hat an der Spitze den Winkel 40°. Die beiden Basiswinkel zusammen messen ①°. Jeder Basiswinkel misst ②°. Ein Basiswinkel und der Winkel an der Spitze zusammen messen ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [140, 70, 110]}, "h": "Die Winkelsumme im Dreieck ist 180°. Die Basiswinkel sind gleich groß.", "w": "Die Basiswinkel zusammen: 180° − 40° = 140°. Jeder Basiswinkel: 140° : 2 = 70°. Ein Basiswinkel plus Spitzenwinkel: 70° + 40° = 110°.", "form": "lueckenweg", "zaehlt": "nein", "r": 15619}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Der Giebel eines Hauses ist ein gleichschenkliges Dreieck. An der Dachtraufe, also an der Basis, misst jeder Winkel 38°. Wie groß ist der Winkel am First an der Spitze?"}, "o": {"wert": 104, "einheit": "°"}, "h": "Beide Basiswinkel sind gleich groß, beide kommen in die Winkelsumme.", "w": "Die zwei Basiswinkel zusammen messen 2 · 38° = 76°. Der Winkel an der Spitze ist 180° − 76° = 104°.", "form": "anwenden", "zaehlt": "ja", "r": 15620}, {"l": "gleichschenklig", "t": "gleichschenklig", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Ein gleichschenkliges Dreieck hat die Basiswinkel 52°. Kim berechnet den Winkel an der Spitze: Zeile 1: Im gleichschenkligen Dreieck sind die beiden Basiswinkel gleich groß. Zeile 2: Beide Basiswinkel zusammen messen 52° + 52° = 104°. Zeile 3: Von der Winkelsumme bleibt nach einem Basiswinkel der Rest übrig, also misst der Winkel an der Spitze 128°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Wie viele Winkel gehören zur Summe von 180°? Welche kennst du schon?", "w": "Von den 180° müssen beide Basiswinkel abgezogen werden: 180° − 104° = 76°. Kim hat in Zeile 3 nur einen Basiswinkel abgezogen. Die Zeilen 1 und 2 sind richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15621}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Zwei Zimmerleute bauen dreieckige Dachrahmen aus Balken. Kim gibt vor: zwei Balken mit 5 m und 7 m Länge, die an der Ecke einen Winkel von 40° einschließen. Welcher Kongruenzsatz sichert, dass alle so gebauten Rahmen deckungsgleich sind?"}, "a": ["SSS: drei Seiten", "SWS: zwei Seiten und der eingeschlossene Winkel", "WSW: eine Seite und zwei anliegende Winkel", "SsW: zwei Seiten und der Winkel der größeren Seite gegenüber"], "o": {"index": 1}, "h": "Wo liegt der gegebene Winkel: zwischen den zwei gegebenen Seiten oder gegenüber einer von ihnen?", "w": "Gegeben sind zwei Seiten (5 m und 7 m) und der Winkel zwischen ihnen. Das ist der Satz SWS: Alle Dreiecke mit diesen Angaben sind deckungsgleich.", "form": "anwenden", "zaehlt": "ja", "r": 15622}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Welche dieser Angaben legt genau ein Dreieck fest (alle so konstruierten Dreiecke sind deckungsgleich)?"}, "a": ["α = 40°, β = 60°, γ = 80°", "c = 6 cm, α = 50°, β = 70°", "a = 3 cm, b = 4 cm, c = 8 cm", "a = 5 cm, b = 7 cm, α = 40° (α liegt der Seite a gegenüber)"], "o": {"index": 1}, "h": "Prüfe jede Angabe: Gibt es einen Kongruenzsatz dazu? Die Seiten müssen außerdem ein Dreieck ergeben.", "w": "Bei c = 6 cm, α = 50° und β = 70° liegen die Winkel an der gegebenen Seite: Das ist WSW, das Dreieck ist festgelegt. Drei Winkel allein legen nur die Form fest. Bei 3 cm, 4 cm und 8 cm ist 3 + 4 = 7 < 8, es gibt kein Dreieck. Bei SsW müsste der Winkel der größeren Seite (7 cm) gegenüberliegen; hier liegt er der kleineren gegenüber (a = 5 cm < b = 7 cm). Zeichnet man b = 7 cm und bei A den Winkel 40°, hat C vom freien Schenkel nur etwa 4,5 cm Abstand: Der Kreis um C mit Radius a = 5 cm schneidet den Schenkel in zwei Punkten, es gibt zwei verschiedene Dreiecke.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15623}, {"l": "kongruenzsatz", "t": "kongruenzsatz", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Zwei Dreiecke haben jeweils die Winkel 50°, 60° und 70°. Alex will ihre Umfänge vergleichen und schreibt auf: Zeile 1: Beide Dreiecke haben die Winkel 50°, 60° und 70°. Zeile 2: Alle drei Winkel stimmen überein, also sind die Dreiecke deckungsgleich. Zeile 3: Deckungsgleiche Dreiecke haben denselben Umfang, also haben beide Dreiecke denselben Umfang. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Ein großes und ein kleines Dreieck können dieselben Winkel haben. Welche Angabe fehlt, damit die Größe festgelegt ist?", "w": "Gleiche Winkel legen nur die Form fest, nicht die Größe: Ein kleines und ein großes Dreieck können dieselben Winkel haben. Aus gleichen Winkeln folgt die Kongruenz nicht: Die Dreiecke könnten zufällig deckungsgleich sein, sicher ist das aber nicht. Für Deckungsgleichheit braucht man mindestens eine passende Seite (etwa WSW). Der Fehler steckt in Zeile 2. Zeile 3 ist aus Zeile 2 richtig gefolgert.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15624}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Seiten eines Dreiecks sind 5 cm und 8 cm lang. Die dritte Seite c muss kürzer als ① cm sein und länger als ② cm. Wenn c eine ganze Zahl in Zentimetern ist, gibt es ③ Möglichkeiten.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [13, 3, 9]}, "h": "Je zwei Seiten müssen zusammen länger sein als die dritte. Die dritte Seite liegt zwischen der Summe und dem Unterschied der beiden anderen.", "w": "c < 5 + 8 = 13 und c > 8 − 5 = 3. Ganze Zahlen von 4 bis 12 (genau c = 4, 5, 6, 7, 8, 9, 10, 11, 12): Das sind 12 − 4 + 1 = 9 Möglichkeiten (13 − 3 − 1 = 9).", "form": "lueckenweg", "zaehlt": "nein", "r": 15625}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Zwei Zeltstangen sind 4 m und 9 m lang. Mit einer dritten Stange, deren Länge eine ganze Zahl in Metern ist, soll ein Dreieck entstehen. Wie lang darf die dritte Stange höchstens sein?"}, "o": {"wert": 12, "einheit": "m"}, "h": "Je zwei Seiten müssen zusammen länger sein als die dritte. Welche Bedingung gilt für die längste Seite?", "w": "Die dritte Seite c muss kürzer sein als 4 + 9 = 13 (und länger als 9 − 4 = 5). Die größte ganze Zahl unter 13 ist 12. Bei 13 würden die Stangen flach aufeinanderliegen.", "form": "anwenden", "zaehlt": "ja", "r": 15626}, {"l": "konstruierbar", "t": "konstruierbar", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Kim behauptet: „Aus Stäben von 3 cm, 4 cm und 7 cm kann man ein Dreieck bilden, denn 3 + 4 = 7.“ Was stimmt?"}, "a": ["Es entsteht ein Dreieck, denn die zwei kürzeren Stäbe sind zusammen nicht kürzer als der längste.", "Es entsteht ein sehr flaches, aber echtes Dreieck.", "Es entsteht kein Dreieck, weil 7 eine Primzahl ist.", "Es entsteht kein Dreieck: Die zwei kürzeren Stäbe müssen zusammen länger sein als der längste. Bei 3 + 4 = 7 liegen sie flach aufeinander."], "o": {"index": 3}, "h": "Prüfe die Bedingung für die längste Seite: Müssen die beiden anderen zusammen länger sein, oder reicht gleich lang?", "w": "Ein Dreieck braucht: zwei Seiten zusammen länger als die dritte. Hier gilt 3 + 4 = 7, nicht länger. Die beiden kurzen Stäbe würden genau auf dem langen Stab liegen, die drei Ecken fallen auf eine Gerade.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15627}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Eine Konstruktionsbeschreibung lautet: 1. Zeichne [AB] mit 7 cm. 2. Zeichne um A einen Kreis mit 5 cm Radius. 3. Zeichne um B einen Kreis mit 6 cm Radius. 4. Ein Schnittpunkt der Kreise ist C. Wie groß ist der Umfang des Dreiecks ABC?"}, "o": {"wert": 18, "einheit": "cm"}, "h": "Der Punkt C liegt auf beiden Kreisen. Welche Entfernungen hat C von A und von B?", "w": "C liegt auf dem Kreis um A, also ist AC = 5 cm, und auf dem Kreis um B, also ist BC = 6 cm. Mit AB = 7 cm ist der Umfang 7 + 5 + 6 = 18 cm.", "form": "anwenden", "zaehlt": "ja", "r": 15628}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst ein Dreieck ABC mit c = 6 cm, α = 35° (bei A) und β = 70° (bei B) konstruieren. Welche Reihenfolge der Schritte ist richtig?"}, "a": ["Strecke [AB] mit 6 cm zeichnen. Bei A den Winkel 35° und bei B den Winkel 70° auf derselben Seite von [AB] antragen. Der Schnittpunkt der beiden freien Schenkel ist C.", "Strecke [AB] mit 6 cm zeichnen. Um A einen Kreis mit 35 cm und um B einen Kreis mit 70 cm Radius zeichnen.", "Bei A den Winkel 35° zeichnen, bei B den Winkel 70° zeichnen. Danach die Strecke [AB] von 6 cm in das entstandene Dreieck einpassen.", "Strecke [AB] mit 6 cm zeichnen. Bei A den Winkel 70° und bei B den Winkel 35° auf derselben Seite von [AB] antragen."], "o": {"index": 0}, "h": "Beginne mit der Seite, die du kennst. Welcher Winkel gehört an welche Ecke?", "w": "Mit der gegebenen Seite beginnen: [AB] = 6 cm. Dann α = 35° bei A und β = 70° bei B auf derselben Seite von [AB] antragen. Die Schenkel schneiden sich in C. Das ist die Konstruktion nach WSW.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15629}, {"l": "planfigur", "t": "planfigur", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Ein Dreieck soll aus der Seite c = 10 cm und den Winkeln α = 50° und γ = 70° konstruiert werden. Zum Antragen an der Seite c braucht man die Winkel an ihren beiden Enden. Wie groß ist der Winkel β bei B?"}, "o": {"wert": 60, "einheit": "°"}, "h": "Von den drei Winkeln liegt einer nicht an der Seite c. Welchen Winkel kannst du mit der Winkelsumme berechnen?", "w": "Die Winkelsumme im Dreieck ist 180°. β = 180° − 50° − 70° = 60°. Jetzt kann man bei A den Winkel 50° und bei B den Winkel 60° an die Seite [AB] antragen.", "form": "umkehren", "zaehlt": "ja", "r": 15630}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Der Satz lautet: „Wenn eine Zahl durch 6 teilbar ist, dann ist sie gerade.“ Welche Aussage nennt den Kehrsatz und beurteilt ihn richtig?"}, "a": ["Kehrsatz: „Wenn eine Zahl nicht durch 6 teilbar ist, dann ist sie nicht gerade.“ Er ist wahr.", "Kehrsatz: „Wenn eine Zahl gerade ist, dann ist sie durch 6 teilbar.“ Er ist wahr, denn der Satz ist wahr.", "Kehrsatz: „Wenn eine Zahl gerade ist, dann ist sie durch 6 teilbar.“ Er ist falsch, denn 8 ist gerade, aber nicht durch 6 teilbar.", "Kehrsatz: „Wenn eine Zahl durch 6 teilbar ist, dann ist sie durch 2 teilbar.“ Er ist wahr."], "o": {"index": 2}, "h": "Beim Kehrsatz werden Wenn-Teil und Dann-Teil vertauscht. Suche danach eine gerade Zahl, die nicht durch 6 teilbar ist.", "w": "Der Satz hat die Form „Wenn A, dann B“ mit A: durch 6 teilbar und B: gerade. Der Kehrsatz heißt „Wenn B, dann A“. Er ist falsch: 8 ist gerade, aber 8 : 6 geht nicht auf. Ein Gegenbeispiel genügt.", "form": "anwenden", "zaehlt": "ja", "r": 15631}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Der Satz „Wenn ein Viereck ein Quadrat ist, dann sind seine Diagonalen gleich lang“ ist wahr. Sein Kehrsatz ist falsch. Welches Viereck ist ein Gegenbeispiel zum Kehrsatz?"}, "a": ["eine Raute mit der Seite 5 cm, die kein Quadrat ist", "ein Parallelogramm mit den Seiten 3 cm und 5 cm und einem Winkel von 60°", "ein Rechteck mit den Seiten 3 cm und 4 cm", "ein Quadrat mit der Seite 4 cm"], "o": {"index": 2}, "h": "Der Kehrsatz lautet: Wenn die Diagonalen gleich lang sind, ist das Viereck ein Quadrat. Gesucht ist ein Viereck mit gleich langen Diagonalen, das kein Quadrat ist.", "w": "Beim Rechteck sind die beiden Diagonalen gleich lang. Hat das Rechteck unterschiedliche Seiten (3 cm und 4 cm), ist es kein Quadrat. Damit ist der Kehrsatz widerlegt. Bei der angebotenen Raute (kein Quadrat) und bei dem Parallelogramm mit 3 cm, 5 cm und 60° sind die Diagonalen verschieden lang.", "form": "umkehren", "zaehlt": "ja", "r": 15632}, {"l": "satz_kehrsatz", "t": "satz_kehrsatz", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Wie viele dieser vier Sätze bleiben wahr, wenn man sie umkehrt? (1) Wenn ein Dreieck gleichseitig ist, dann sind alle seine Winkel 60° groß. (2) Wenn eine Zahl durch 10 teilbar ist, dann ist sie durch 5 teilbar. (3) Wenn ein Viereck eine Raute ist, dann hat es vier gleich lange Seiten. (4) Wenn eine Zahl durch 4 teilbar ist, dann ist sie gerade."}, "o": {"wert": 2}, "h": "Kehre jeden Satz um und suche ein Gegenbeispiel. Eine Zahl, die durch 5, aber nicht durch 10 teilbar ist, hilft bei Satz (2).", "w": "Die Kehrsätze: (1) Wenn alle Winkel 60° sind, ist das Dreieck gleichseitig: wahr. (2) Wenn eine Zahl durch 5 teilbar ist, ist sie durch 10 teilbar: falsch (Gegenbeispiel 15). (3) Wenn ein Viereck vier gleich lange Seiten hat, ist es eine Raute: wahr. (4) Wenn eine Zahl gerade ist, ist sie durch 4 teilbar: falsch (Gegenbeispiel 6). Zwei Sätze bleiben wahr.", "form": "anwenden", "zaehlt": "ja", "r": 15633}]$auf$::jsonb),
    (92, 'geometrie.winkelsaetze', 658, 18, $auf$[{"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Zwei Geraden schneiden sich. Der Winkel α ist dreimal so groß wie sein Nebenwinkel β. Zusammen ergeben α und β ①°. Dann ist β = ②° und α = ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [180, 45, 135]}, "h": "Nebenwinkel liegen nebeneinander an einer Geraden. Wenn α das Dreifache von β ist, besteht die Summe aus 4 gleich großen Teilen.", "w": "Nebenwinkel ergeben 180°. Die Summe besteht aus 3 Teilen für α und 1 Teil für β, zusammen 4 Teile. β = 180° : 4 = 45°. α = 180° − 45° = 135° (das ist 3 · 45°).", "form": "lueckenweg", "zaehlt": "nein", "r": 15659}, {"l": "scheitel_neben", "t": "scheitel_neben", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Zwei gerade Straßen kreuzen sich. Einer der vier Winkel zwischen ihnen misst 83°. Wie groß ist jeder der beiden Winkel, die an diesen Winkel angrenzen?"}, "o": {"wert": 97, "einheit": "°"}, "h": "Winkel, die nebeneinander an einer Geraden liegen, bilden zusammen einen gestreckten Winkel.", "w": "Die angrenzenden Winkel sind Nebenwinkel des 83°-Winkels. Nebenwinkel ergeben zusammen 180°: 180° − 83° = 97°.", "form": "anwenden", "zaehlt": "ja", "r": 15660}, {"l": "stufen_wechsel", "t": "stufen_wechsel", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Die Geraden g und h sind parallel. Die Gerade q schneidet beide. An g liegt ein Winkel α = 73°. Sein Wechselwinkel an h heißt β, und der Nebenwinkel von β heißt γ. Wie groß ist γ?"}, "o": {"wert": 107, "einheit": "°"}, "h": "Wechselwinkel an Parallelen sind gleich groß. Danach brauchst du noch den Nebenwinkel.", "w": "Wechselwinkel an Parallelen sind gleich groß: β = α = 73°. Der Nebenwinkel von β ergänzt zu 180°: γ = 180° − 73° = 107°.", "form": "anwenden", "zaehlt": "ja", "r": 15661}, {"l": "stufen_wechsel", "t": "stufen_wechsel", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Die Geraden g und h sind parallel, q schneidet beide. Der Winkel α an g misst 68°. Kim bestimmt weitere Winkel an h: Zeile 1: α und β sind Stufenwinkel, also gilt β = 68°. Zeile 2: Der Winkel γ ist der Nebenwinkel von β, also gilt γ = 68°. Zeile 3: Der Winkel δ ist der Scheitelwinkel von γ, also gilt δ = 68°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Nebenwinkel liegen nebeneinander an einer Geraden. Wie groß ist die Summe zweier Nebenwinkel?", "w": "Nebenwinkel ergeben zusammen 180°, also γ = 180° − 68° = 112°. Der Fehler steckt in Zeile 2. Zeile 3 ist richtig weitergerechnet: Scheitelwinkel sind gleich groß, δ = γ. Mit dem richtigen γ wäre δ = 112°.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15662}, {"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 2, "g": "einkleidung", "y": "auswahl", "f": {"text": "Zwei Wanderwege werden von einem Querweg geschnitten. Kim misst zwei Stufenwinkel: 78° und 82°. Was folgt daraus?"}, "a": ["Die Wege sind parallel, denn 78° und 82° liegen nur 4° auseinander.", "Die Wege sind parallel, denn 78° + 82° = 160° liegt nahe bei 180°.", "Die Wege sind nicht parallel, denn Stufenwinkel an Parallelen müssten gleich groß sein.", "Man kann nichts sagen, weil nur zwei Winkel gemessen wurden."], "o": {"index": 2}, "h": "Prüfe: Müssen gleich liegende Stufenwinkel bei parallelen Geraden gleich groß sein?", "w": "Bei parallelen Geraden sind Stufenwinkel gleich groß. Hier ist 78° ≠ 82°. Deshalb sind die beiden Wege nicht parallel.", "form": "anwenden", "zaehlt": "ja", "r": 15663}, {"l": "parallel_pruefen", "t": "parallel_pruefen", "p": "uebung", "s": 3, "g": "pruefung", "y": "zahl", "f": {"text": "Die Geraden g und h werden von einer Geraden q geschnitten. Ein Paar Wechselwinkel misst (5x − 20)° und (3x + 14)°. Für welchen Wert von x sind g und h parallel?"}, "o": {"wert": 17}, "h": "Parallel heißt: Die Wechselwinkel sind gleich groß. Stelle eine Gleichung auf und löse sie.", "w": "Parallele Geraden haben gleich große Wechselwinkel: 5x − 20 = 3x + 14. Es folgt 2x = 34 und x = 17. Probe: Beide Winkel messen 65°.", "form": "umkehren", "zaehlt": "ja", "r": 15664}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Drei Wanderwege bilden ein Dreieck. Die Winkel verhalten sich wie 5 : 6 : 7. Wie groß ist der größte Winkel in Grad?"}, "o": {"wert": 70, "einheit": "°"}, "h": "Die Winkelsumme im Dreieck ist 180°. Wie viele gleich große Teile entstehen insgesamt?", "w": "Es sind 5 + 6 + 7 = 18 Teile. Ein Teil ist 180° : 18 = 10°. Der größte Winkel hat 7 Teile: 7 · 10° = 70°.", "form": "anwenden", "zaehlt": "ja", "r": 15665}, {"l": "innenwinkelsumme", "t": "innenwinkelsumme", "p": "uebung", "s": 3, "g": "begruenden", "y": "auswahl", "f": {"text": "Welche Begründung zeigt für jedes Dreieck, dass die Winkelsumme 180° beträgt?"}, "a": ["Man zeichnet durch eine Ecke die Parallele zur gegenüberliegenden Seite. Wechselwinkel zeigen, dass die drei Winkel zusammen einen gestreckten Winkel bilden.", "Kim hat in drei Dreiecken die Winkel gemessen und jedes Mal etwa 180° erhalten.", "Ein Dreieck hat drei Ecken, und 3 · 60° = 180°."], "o": {"index": 0}, "h": "Ein Beweis muss für jedes Dreieck gelten und sich auf bekannte Sätze stützen, etwa Wechselwinkel an Parallelen.", "w": "Die Parallele durch eine Ecke bildet mit den Dreiecksseiten zwei Paare von Wechselwinkeln. Zusammen mit dem dritten Winkel liegen alle drei Winkel an einer Geraden und ergeben 180°. Das gilt für jedes Dreieck. Messungen und der Sonderfall des gleichseitigen Dreiecks zeigen das nicht allgemein.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15666}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "In einem Dreieck misst der Innenwinkel α genau 38°, und der Außenwinkel an C misst 121°. Nach dem Außenwinkelsatz ist β = ①°. Der Innenwinkel an C ist ②°. Alle drei Innenwinkel zusammen sind ③°.", "schablone": "① = □; ② = □; ③ = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [83, 59, 180]}, "h": "Der Außenwinkel ist so groß wie die beiden nicht anliegenden Innenwinkel zusammen. Der Innenwinkel an C ist sein Nebenwinkel.", "w": "β = 121° − 38° = 83°. Der Innenwinkel an C ist der Nebenwinkel des Außenwinkels: 180° − 121° = 59°. Die Summe 38° + 83° + 59° = 180° bestätigt die Rechnung.", "form": "lueckenweg", "zaehlt": "nein", "r": 15667}, {"l": "aussenwinkel", "t": "aussenwinkel", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Dreieck ABC hat die Innenwinkel α = 47° und β = 65°. Kim verlängert die Seite [AC] über C hinaus. Wie groß ist der Außenwinkel an C, der an γ angrenzt?"}, "o": {"wert": 112, "einheit": "°"}, "h": "Der Außenwinkel ist so groß wie die beiden Innenwinkel zusammen, die nicht an ihm liegen.", "w": "Der Außenwinkel an C ist so groß wie die beiden anderen Innenwinkel zusammen: 47° + 65° = 112°. Probe: γ = 180° − 47° − 65° = 68°, und 180° − 68° = 112°.", "form": "anwenden", "zaehlt": "ja", "r": 15668}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Ein Gartenhaus hat als Grundriss ein regelmäßiges Zwölfeck. Wie groß ist jeder Innenwinkel des Grundrisses in Grad?"}, "o": {"wert": 150, "einheit": "°"}, "h": "Wie groß ist die Winkelsumme im Zwölfeck? Wie viele gleich große Winkel hat es?", "w": "Die Winkelsumme im Zwölfeck ist (12 − 2) · 180° = 1 800°. Alle 12 Winkel sind gleich groß: 1 800° : 12 = 150°.", "form": "anwenden", "zaehlt": "ja", "r": 15669}, {"l": "vieleck", "t": "vieleck", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Die Winkelsumme eines konvexen Vielecks beträgt 2 340°. In wie viele Dreiecke lässt sich das Vieleck durch Diagonalen von einer Ecke aus zerlegen?"}, "o": {"wert": 13, "einheit": "Dreiecke"}, "h": "Jedes Dreieck bringt 180° zur Winkelsumme. Wie oft passen 180° in 2 340°?", "w": "Bei der Zerlegung von einer Ecke aus entstehen (n − 2) Dreiecke, jedes bringt 180°. Aus (n − 2) · 180° = 2 340° folgt n − 2 = 13. Es sind 13 Dreiecke.", "form": "umkehren", "zaehlt": "ja", "r": 15670}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Platz in Lissabon wird mit zwei regelmäßigen Zwölfecken und einer dritten Sorte regelmäßiger Vielecke so gepflastert, dass sich um jeden Eckpunkt genau diese drei Vielecke lückenlos treffen. Wie groß ist der Innenwinkel der dritten Sorte in Grad?"}, "o": {"wert": 60, "einheit": "°"}, "h": "Wie groß ist der Innenwinkel eines regelmäßigen Zwölfecks? Um einen Punkt herum ergeben alle Winkel 360°.", "w": "Der Innenwinkel des regelmäßigen Zwölfecks ist 150°. Zwei davon sind 300°. Es fehlen 360° − 300° = 60°. Das ist der Innenwinkel eines gleichseitigen Dreiecks.", "form": "anwenden", "zaehlt": "ja", "r": 15671}, {"l": "parkett", "t": "parkett", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Kim sagt: „Mit regelmäßigen Fünfecken allein kann man den Boden lückenlos auslegen, denn 360° : 5 = 72° ist eine ganze Zahl.“ Welche Prüfung ist richtig?"}, "a": ["Der Innenwinkel des regelmäßigen Fünfecks ist 108°. Die Zahl 360 lässt sich nicht ganzzahlig durch 108 teilen. Die Fünfecke passen nicht lückenlos.", "Die Prüfung stimmt: 360° wird durch die Zahl der Ecken geteilt, das geht auf.", "Der Innenwinkel ist 72°, und 360° : 72° = 5. Die Fünfecke passen lückenlos.", "Der Innenwinkel ist 108°. Weil 108° + 108° + 108° = 324° fast 360° ergibt, passen sie nach etwas Schieben."], "o": {"index": 0}, "h": "Entscheidend ist der Innenwinkel der Fläche, nicht die Zahl der Ecken. Teilt er 360° ohne Rest?", "w": "Der Innenwinkel des regelmäßigen Fünfecks ist (5 − 2) · 180° : 5 = 108°. 360° : 108° ist nicht ganzzahlig (3,33 ...). Um einen Punkt bleibt eine Lücke. Fünfecke allein passen nicht lückenlos.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15672}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Ein Segel hat die Form eines Vierecks ABCD mit α = 80°, β = 95° und γ = 70°. Die Seite [AD] wird über D hinaus verlängert. Wie groß ist der Winkel, den die Verlängerung mit [DC] einschließt?"}, "o": {"wert": 65, "einheit": "°"}, "h": "Berechne zuerst δ im Viereck. Die Verlängerung bildet mit [DA] einen gestreckten Winkel.", "w": "Die Winkelsumme im Viereck ist 360°. δ = 360° − 80° − 95° − 70° = 115°. Die Verlängerung von [AD] und die Seite [DA] liegen auf einer Geraden, der gesuchte Winkel ist der Nebenwinkel von δ: 180° − 115° = 65°.", "form": "anwenden", "zaehlt": "ja", "r": 15673}, {"l": "figuren", "t": "figuren", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "In einem Trapez ABCD mit AB ∥ CD gilt α = 70° und β = 80°. Wie groß ist die Summe der beiden Winkel γ und δ?"}, "o": {"wert": 210, "einheit": "°"}, "h": "Winkel an den beiden Schenkeln zwischen den Parallelen ergeben jeweils 180°.", "w": "Zwischen den Parallelen AB und CD gilt: α + δ = 180° und β + γ = 180°. Also δ = 110° und γ = 100°, zusammen 210°. Probe über die Winkelsumme im Viereck: 360° − 70° − 80° = 210°.", "form": "anwenden", "zaehlt": "ja", "r": 15674}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Du willst beweisen, dass die Winkelsumme in jedem Viereck 360° beträgt. Welcher Ablauf ist ein richtiger Beweis?"}, "a": ["Man misst bei einem Viereck alle Winkel und addiert. Es kommt 360° heraus, also gilt es immer.", "Ein Viereck hat 4 Ecken. Jede Ecke hat 90°. Also 4 · 90° = 360°.", "Man zeichnet beide Diagonalen. Es entstehen 4 Dreiecke zu je 180°, also 4 · 180° = 720° für das Viereck.", "Man zeichnet eine Diagonale, die im Inneren des Vierecks liegt, und zerlegt das Viereck in zwei Dreiecke. Jedes Dreieck hat die Winkelsumme 180°. Die Winkel der Dreiecke bilden zusammen die Viereckswinkel: 180° + 180° = 360°."], "o": {"index": 3}, "h": "Ein Beweis gilt für jedes Viereck. Welcher Satz über Dreiecke kann dabei helfen?", "w": "Eine im Inneren liegende Diagonale zerlegt das Viereck in zwei Dreiecke. Die Winkel der Dreiecke ergeben genau die vier Winkel des Vierecks: 2 · 180° = 360°. Der Ablauf stützt sich auf den bekannten Satz über die Winkelsumme im Dreieck.", "form": "bruecke", "zaehlt": "ja", "r": 15675}, {"l": "beweisen", "t": "beweisen", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex beweist, dass die drei Außenwinkel eines Dreiecks zusammen 360° ergeben, und schreibt auf: Zeile 1: An jeder Ecke ergeben Innenwinkel und Außenwinkel zusammen 180°. Zeile 2: An den drei Ecken ergibt das 3 · 180° = 540°. Zeile 3: Die drei Innenwinkel ergeben zusammen 180°. Zeile 4: Die Außenwinkel ergeben also die Summe aus den 540° und den 180° der Innenwinkel, das sind 720°. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3", "In Zeile 4"], "o": {"index": 3}, "h": "Von den 540° gehören 180° zu den Innenwinkeln. Was bleibt für die Außenwinkel übrig?", "w": "Von den 540° gehören 180° zu den Innenwinkeln. Die Außenwinkel sind der Rest: 540° − 180° = 360°. Alex hat in Zeile 4 addiert statt subtrahiert. Die Zeilen 1 bis 3 sind richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15676}]$auf$::jsonb),
    (111, 'terme.potenzgesetze_natuerlich', 166, 15, $auf$[{"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du vereinfachst das Produkt 3³ · 3² · 3². Die Basis 3 bleibt stehen, die Hochzahlen werden verrechnet. Das Ergebnis ist die Potenz 3^①. Der Wert dieser Potenz ist ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [7, 2187]}, "h": "Gleiche Basis beim Malnehmen: Was passiert mit den Hochzahlen? Rechne danach die Potenz aus.", "w": "Die Hochzahlen werden addiert: 3 + 2 + 2 = 7. Also ist das Produkt 3⁷. Ausgerechnet: 3⁷ = 2 187.", "form": "lueckenweg", "zaehlt": "nein", "r": 15167}, {"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Aus einer Zelle entstehen durch 4 Teilungen 2⁴ Zellen. Jede dieser Zellen teilt sich danach noch 5-mal weiter. Wie viele Zellen sind es nach den insgesamt 9 Teilungen?"}, "o": {"wert": 512, "einheit": "Zellen"}, "h": "Bei jeder Teilung verdoppelt sich die Zahl der Zellen. Wie oft wird insgesamt mit 2 malgenommen?", "w": "Erst gibt es 2⁴ = 16 Zellen. Jede teilt sich 5-mal weiter: 2⁵ = 32 Zellen aus einer. Insgesamt 2⁴ · 2⁵ = 2⁹ = 512 Zellen. Gleiche Basis beim Malnehmen: die Hochzahlen addieren.", "form": "anwenden", "zaehlt": "ja", "r": 15168}, {"l": "mal_gleiche_basis", "t": "mal_gleiche_basis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Kim soll 3⁴ · 3² vereinfachen und schreibt auf: Zeile 1: Bei beiden Faktoren ist die Basis 3, also gleich. Zeile 2: Bei gleicher Basis werden die Hochzahlen malgenommen. Zeile 3: Also ist 3⁴ · 3² = 3⁸. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 1}, "h": "Was geschieht mit den Hochzahlen, wenn zwei Potenzen mit gleicher Basis malgenommen werden? Schreibe 3⁴ · 3² einmal als Faktoren aus.", "w": "3⁴ · 3² = (3 · 3 · 3 · 3) · (3 · 3) hat 6 Faktoren 3, also 3⁶. Die Hochzahlen werden addiert, nicht malgenommen. Der Fehler steckt in Zeile 2. Zeile 3 rechnet mit der falschen Regel richtig weiter.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15169}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Das Volumen eines Würfels mit der Kante a ist a³. Ein Würfel hat die Kante 4 m, ein zweiter die Kante 25 m. Wie groß ist das Produkt der beiden Volumen (in m⁶)?"}, "o": {"wert": 1000000, "einheit": "m⁶"}, "h": "Beide Volumen haben die gleiche Hochzahl. Fasse zuerst die Basen zusammen, bevor du ausrechnest.", "w": "Die Volumen sind 4³ und 25³. Gleicher Exponent: 4³ · 25³ = (4 · 25)³ = 100³ = 1 000 000 m⁶.", "form": "anwenden", "zaehlt": "ja", "r": 15170}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "auswahl", "f": {"text": "Du sollst 2⁵ · 5⁵ im Kopf ausrechnen. Welcher Weg ist am geschicktesten, also am wenigsten Rechenaufwand? (Mehrere Wege können zum richtigen Ergebnis führen.)"}, "a": ["Gleiche Hochzahl: 2 · 5 = 10 und 5 + 5 = 10, also 10¹⁰.", "Erst 2⁵ = 32 und 5⁵ = 3 125 ausrechnen und dann 32 · 3 125 schriftlich rechnen.", "Gleiche Basis gibt es nicht, also lässt sich nichts vereinfachen.", "Gleiche Hochzahl: (2 · 5)⁵ = 10⁵ = 100 000."], "o": {"index": 3}, "h": "Prüfe zuerst: Welche Zahlen sind bei beiden Faktoren gleich, die Basen oder die Hochzahlen?", "w": "Beide Potenzen haben die Hochzahl 5. Dann gilt aⁿ · bⁿ = (a · b)ⁿ: 2⁵ · 5⁵ = (2 · 5)⁵ = 10⁵ = 100 000. Das geht im Kopf.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15171}, {"l": "gleicher_exponent", "t": "gleicher_exponent", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche natürliche Zahl im Kästchen gilt 14⁴ = 2⁴ · □⁴ ?"}, "o": {"wert": 7}, "h": "Bei gleicher Hochzahl werden die Basen malgenommen. Welche Zahl ergibt mit 2 zusammen die Basis 14?", "w": "Nach dem Gesetz aⁿ · bⁿ = (a · b)ⁿ muss 2 · □ = 14 gelten. Also ist □ = 7. Probe: 2⁴ · 7⁴ = 16 · 2 401 = 38 416 = 14⁴.", "form": "umkehren", "zaehlt": "ja", "r": 15172}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "Jede Person, die einen Kettenbrief bekommt, schickt ihn an 2³ neue Personen weiter. Die erste Person verschickt ihn in Runde 1. In Runde 4 bekommen (2³)⁴ Personen den Brief neu. Wie viele Personen sind das?"}, "o": {"wert": 4096, "einheit": "Personen"}, "h": "Die Potenz 2³ wird noch einmal hoch 4 genommen. Wie viele Faktoren 2 sind das zusammen?", "w": "(2³)⁴ = 2³ · 2³ · 2³ · 2³ = 2¹² = 4 096. Bei einer Potenz von einer Potenz werden die Hochzahlen malgenommen: 3 · 4 = 12.", "form": "anwenden", "zaehlt": "ja", "r": 15173}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 2, "g": "darstellung", "y": "auswahl", "f": {"text": "Kim soll (x²)³ vereinfachen. Welche Aussage beschreibt die Potenz richtig?"}, "a": ["x⁵, denn bei einer Potenz von einer Potenz werden die Hochzahlen addiert.", "x⁹, denn es sind 3 Faktoren mit jeweils 3 Faktoren x.", "x⁶, denn x² steht dreimal als Faktor da: x² · x² · x² hat zusammen 6 Faktoren x."], "o": {"index": 2}, "h": "Schreibe (x²)³ als Produkt: Wie oft steht der Faktor x² da? Aus wie vielen Faktoren x besteht jeder davon?", "w": "(x²)³ = x² · x² · x². Jedes x² besteht aus 2 Faktoren x, es gibt 3 davon: zusammen 2 · 3 = 6 Faktoren. Also (x²)³ = x⁶.", "form": "bruecke", "zaehlt": "ja", "r": 15174}, {"l": "potenz_von_potenz", "t": "potenz_von_potenz", "p": "uebung", "s": 3, "g": "rueckwaerts", "y": "zahl", "f": {"text": "Für welche Hochzahl n gilt (5ⁿ)⁴ = 5²⁴?"}, "o": {"wert": 6}, "h": "Wie hängen die Hochzahlen n, 4 und 24 bei einer Potenz von einer Potenz zusammen?", "w": "Bei (5ⁿ)⁴ werden die Hochzahlen malgenommen: n · 4 = 24. Also ist n = 24 : 4 = 6. Probe: (5⁶)⁴ = 5²⁴.", "form": "umkehren", "zaehlt": "ja", "r": 15175}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 1, "g": "direkt", "y": "luecken", "f": {"text": "Du berechnest 4⁷ : 4⁵ Schritt für Schritt. Erst vereinfachst du zu einer einzigen Potenz mit der Basis 4: Das ist 4^①. Dann rechnest du diese Potenz aus: ②.", "schablone": "① = □; ② = □", "hinweis": "Je Lücke eine ganze Zahl (mit Minus, falls negativ)."}, "o": {"werte": [2, 16]}, "h": "Bei gleicher Basis beim Teilen werden die Hochzahlen verrechnet. Wie? Die Basis bleibt.", "w": "Teilen mit gleicher Basis: Die Hochzahlen werden subtrahiert, 7 − 5 = 2. Also 4⁷ : 4⁵ = 4². Ausgerechnet: 4² = 16.", "form": "lueckenweg", "zaehlt": "nein", "r": 15176}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 2, "g": "einkleidung", "y": "zahl", "f": {"text": "In einem Hafenlager stehen 5⁶ Bananenkisten. Ein Lkw nimmt bei jeder Fahrt 5⁴ Kisten mit. Wie viele Fahrten sind nötig, bis das Lager leer ist?"}, "o": {"wert": 25, "einheit": "Fahrten"}, "h": "Gesucht ist, wie oft 5⁴ in 5⁶ passt. Teile die beiden Potenzen mit gleicher Basis.", "w": "Gesucht ist 5⁶ : 5⁴. Bei gleicher Basis subtrahiert man die Hochzahlen: 6 − 4 = 2. Also 5² = 25 Fahrten.", "form": "anwenden", "zaehlt": "ja", "r": 15177}, {"l": "geteilt_gleiche_basis", "t": "geteilt_gleiche_basis", "p": "uebung", "s": 3, "g": "fehler", "y": "auswahl", "f": {"text": "Alex soll 7⁹ : 7⁴ berechnen und schreibt auf: Zeile 1: Die Basis ist gleich, also werden die Hochzahlen subtrahiert. Zeile 2: Es gilt 9 − 4 = 5, also ist 7⁹ : 7⁴ = 7⁵. Zeile 3: Ausgerechnet ist 7⁵ = 7 · 5 = 35. In welcher Zeile passiert der erste Fehler?"}, "a": ["In Zeile 1", "In Zeile 2", "In Zeile 3"], "o": {"index": 2}, "h": "Was bedeutet 7⁵? Schreibe es als Produkt aus Faktoren.", "w": "7⁵ = 7 · 7 · 7 · 7 · 7 = 16 807. Die Hochzahl sagt, wie oft die Basis als Faktor vorkommt; man rechnet nicht Basis mal Hochzahl. Der Fehler steckt in Zeile 3. Die Zeilen 1 und 2 sind richtig.", "form": "fehler_detektiv", "zaehlt": "ja", "r": 15178}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 2, "g": "mehrschritt", "y": "zahl", "f": {"text": "Beim Reisfeld-Spiel liegt auf Feld 1 ein Korn, auf jedem nächsten Feld doppelt so viele wie auf dem Feld davor. Auf Feld 11 liegen 2¹⁰ Körner, auf Feld 7 liegen 2⁶ Körner. Wie oft ist die Zahl der Körner auf Feld 7 in der Zahl auf Feld 11 enthalten?"}, "o": {"wert": 16}, "h": "Gesucht ist ein Quotient. Beide Zahlen sind Potenzen von 2.", "w": "Gesucht ist 2¹⁰ : 2⁶. Gleiche Basis beim Teilen: Hochzahlen subtrahieren, 10 − 6 = 4. Also 2⁴ = 16. Auf Feld 11 liegen 16-mal so viele Körner wie auf Feld 7.", "form": "anwenden", "zaehlt": "ja", "r": 15179}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 3, "g": "pruefung", "y": "auswahl", "f": {"text": "Eines dieser Produkte lässt sich mit keinem Potenzgesetz zu einer einzigen Potenz zusammenfassen. Welches?"}, "a": ["2⁵ · 2⁴", "2⁵ · 3⁴", "2⁵ · 3⁵", "(2⁵)⁴"], "o": {"index": 1}, "h": "Prüfe bei jedem Produkt: Sind die Basen gleich, oder sind die Hochzahlen gleich, oder steckt eine Potenz in einer Potenz?", "w": "2⁵ · 2⁴ = 2⁹ (gleiche Basis). 2⁵ · 3⁵ = 6⁵ (gleiche Hochzahl). (2⁵)⁴ = 2²⁰. Bei 2⁵ · 3⁴ sind Basen und Hochzahlen verschieden, hier hilft kein Potenzgesetz.", "form": "verfahren_waehlen", "zaehlt": "ja", "r": 15180}, {"l": "anwenden", "t": "anwenden", "p": "uebung", "s": 3, "g": "verknuepfen", "y": "zahl", "f": {"text": "Eine Rechenmaschine soll (2⁴ · 2⁵)² : 2¹⁰ berechnen, ohne die Potenzen einzeln auszurechnen. Welches Ergebnis ist richtig?"}, "o": {"wert": 256}, "h": "Fasse zuerst die Klammer zusammen. Dann nimm die Potenz von der Potenz und teile am Ende.", "w": "Klammer: 2⁴ · 2⁵ = 2⁹. Potenz von einer Potenz: (2⁹)² = 2¹⁸. Teilen: 2¹⁸ : 2¹⁰ = 2⁸ = 256.", "form": "anwenden", "zaehlt": "ja", "r": 15181}]$auf$::jsonb)
  ) x(id, schluessel, max_r, soll, aufgaben) loop
    if not exists (select 1 from schule.einheit ei join schule.thema th on th.id = ei.thema_id where ei.id = e.id and th.schluessel = e.schluessel) then
      fehler := fehler || ('Einheit ' || e.id || ' ist nicht ' || e.schluessel)::text; continue; end if;
    if (select coalesce(max(reihenfolge), 0) from schule.aufgabe where einheit_id = e.id and pool = 'uebung' and reihenfolge <= e.max_r) <> e.max_r then
      fehler := fehler || ('Einheit ' || e.id || ': Bestand hat sich seit dem Lesen geändert')::text; continue; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.pool = 'uebung' and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x)) then
      fehler := fehler || ('Einheit ' || e.id || ': Reihenfolge-Nummern des Pakets sind schon belegt (Paket schon eingespielt?)')::text; continue; end if;
    if exists (select 1 from jsonb_array_elements(e.aufgaben) x where not exists (select 1 from schule.einheit ei, jsonb_array_elements(ei.inhalt->'etappen') et where ei.id = e.id and et->>'lernziel' = x->>'l')) then
      fehler := fehler || ('Einheit ' || e.id || ': Lernziel unbekannt')::text; continue; end if;
    select count(*) into vorher from schule.aufgabe where einheit_id = e.id;
    n := schule.aufgaben_einfuegen(e.id, e.aufgaben);
    if n <> e.soll or (select count(*) from schule.aufgabe where einheit_id = e.id) <> vorher + e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': ' || n || ' statt ' || e.soll || ' eingefügt')::text; end if;
    if (select count(*) from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung' and a.form is not null and a.zaehlt is not null) <> e.soll then
      fehler := fehler || ('Einheit ' || e.id || ': form/zaehlt nicht übernommen')::text; end if;
    if exists (select 1 from schule.aufgabe a where a.einheit_id = e.id and a.reihenfolge in (select (x->>'r')::int from jsonb_array_elements(e.aufgaben) x) and a.pool = 'uebung'
               and not coalesce((schule.antwort_bewerten(a, case a.antworttyp when 'zahl' then jsonb_build_object('wert', '0') else '{}'::jsonb end)->>'format_ok') is not null, false)) then
      fehler := fehler || ('Einheit ' || e.id || ': eine neue Aufgabe lässt sich nicht bewerten')::text; end if;
    gesamt := gesamt + n;
  end loop;
  if gesamt <> 207 then fehler := fehler || ('zusammen ' || gesamt || ' statt 207')::text; end if;
  if array_length(fehler, 1) > 0 then raise exception 'Vorrats-Aufgaben ABBRUCH, alles zurückgerollt: %', array_to_string(fehler, ' | '); end if;
end $einspielen$;
