    ('R15-V048', 54, 15688, '10387c7409d33a0c7b6a5f8ac87fc372', 'zahl', 'achsenspiegelung', null, $rbf${"wert": -3}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "-5", "text": "an der y-Achse gespiegelt statt am Kanal", "fehlbild": "fb.deckungsgleich.an_koordinatenachse_gespiegelt", "regel": "id.geometrie.deckungsgleich"}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "6", "text": "die x-Koordinate von A zum Wert der Achse addiert", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "3", "text": "den Abstand falsch herum abgetragen und das Vorzeichen vertauscht", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V049', 54, 15689, 'fe04fdf70f2274df0e1ede386ac218cf', 'auswahl', 'achsenspiegelung', '6cb911a71d07c5765726ebd2cb6fd197', $rbf${"index": 1}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "index", "luecke": null, "wert": "0", "text": "diese Zeile ist richtig; der Fehler steckt woanders", "fehlbild": null, "regel": null}, {"nr": 2, "art": "index", "luecke": null, "wert": "2", "text": "diese Zeile ist nur die Folge des ersten Fehlers", "fehlbild": null, "regel": null}]$rbf$::jsonb),
    ('R15-V050', 54, 15690, '5a17f9054ddeef6f83caf2e2d9355f6c', 'zahl', 'mittelsenkrechte', null, $rbf${"wert": 3}$rbf$::jsonb, null, $rbf$[{"nr": 1, "art": "zahl", "luecke": null, "wert": "9", "text": "die halbe Länge der Strecke statt die Lage der Mitte genommen", "fehlbild": "fb.abstand.halbe_laenge_statt_mitte", "regel": "id.geometrie.abstand"}, {"nr": 2, "art": "zahl", "luecke": null, "wert": "18", "text": "die ganze Länge der Strecke genommen", "fehlbild": null, "regel": null}, {"nr": 3, "art": "zahl", "luecke": null, "wert": "6", "text": "die beiden x-Koordinaten nicht halbiert", "fehlbild": null, "regel": null}]$rbf$::jsonb),
